window.CGL_DATA=window.CGL_DATA||{};window.CGL_DATA["CGL-10-OCT-2026-SHIFT-2"]={"id":"CGL-10-OCT-2026-SHIFT-2","title":"CGL 10 OCT 2026 SHIFT 2","order":["REASONING","GK","MATH","ENGLISH"],"marking":{"correct":2,"negative":0.5},"qualifying":[],"sections":{"REASONING":{"seconds":900,"questions":[{"no":1,"local_id":"50001","quid":"Q1000073681","section":"REASONING","topic":"Figure Completing","question":{"en":"Select the figure among the given options that, when placed in the question mark (?), will complete the following pattern. (Rotation is NOT allowed)<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"दिए गए विकल्पों में से वह आकृति चुनिए जो प्रश्न चिह्न (?) के स्थान पर रखने पर निम्नलिखित पैटर्न को पूरा करेगी। (घुमाने की अनुमति नहीं है)<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"2","solution":{"en":"The missing quarter must have the circle with a cross, the black bar at the bottom and the double slanting line, matching the other quarters.<br>Figure (B) fits without rotation.<br><br><b>Hence, the correct answer is option (2): Figure (2).</b>","hi":"लुप्त भाग में क्रॉस वाला वृत्त, नीचे काली पट्टी और दोहरी तिरछी रेखा होनी चाहिए, जो अन्य भागों से मेल खाए।<br>आकृति (B) बिना घुमाए ठीक बैठती है।<br><br><b>अतः सही उत्तर विकल्प (2): आकृति (2) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q1_opt4.jpg"]}}},{"no":2,"local_id":"50002","quid":"Q1000073682","section":"REASONING","topic":"Direction & Distance","question":{"en":"Seven points A, B, C, D, E, F and G are drawn on a paper. A is 10 m west of C, which is 12 m north of E. B is 8 m east of E. B is 7 m south of D, which is 15 m east of F. G is 17 m south of F.<br><br>In which direction is point A with respect to point B? [SSC CGL 10/10/26 Shift 2]","hi":"एक कागज़ पर सात बिंदु A, B, C, D, E, F और G बनाए गए हैं। A, C से 10 m पश्चिम में है, जो E से 12 m उत्तर में है। B, E से 8 m पूर्व में है। B, D से 7 m दक्षिण में है, जो F से 15 m पूर्व में है। G, F से 17 m दक्षिण में है।<br><br>बिंदु A, बिंदु B के सापेक्ष किस दिशा में है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"North-east","hi":"उत्तर-पूर्व"},"2":{"en":"North-west","hi":"उत्तर-पश्चिम"},"3":{"en":"South-east","hi":"दक्षिण-पूर्व"},"4":{"en":"South-west","hi":"दक्षिण-पश्चिम"}},"answer":"2","solution":{"en":"Take E at (0, 0): C = (0, 12), A = (−10, 12), B = (8, 0).<br>A is 18 m to the west and 12 m to the north of B.<br>So A is North-west of B.<br><br><b>Hence, the correct answer is option (2): North-west.</b>","hi":"E को (0, 0) पर लें: C = (0, 12), A = (−10, 12), B = (8, 0)<br>A, B से 18 m पश्चिम और 12 m उत्तर में है।<br>अतः A, B के उत्तर-पश्चिम में है।<br><br><b>अतः सही उत्तर विकल्प (2): उत्तर-पश्चिम है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":3,"local_id":"50003","quid":"Q1000073683","section":"REASONING","topic":"Embedded Figures","question":{"en":"Select the option in which the given figure is embedded.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"वह विकल्प चुनिए जिसमें दी गई आकृति निहित है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"2","solution":{"en":"The given outline is formed by parts of the overlapping rectangle, pentagon and hexagon in figure (B).<br><br><b>Hence, the correct answer is option (2): Figure (2).</b>","hi":"दी गई रूपरेखा आकृति (B) में एक-दूसरे पर चढ़े आयत, पंचभुज और षट्भुज के भागों से बनती है।<br><br><b>अतः सही उत्तर विकल्प (2): आकृति (2) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q3_opt4.jpg"]}}},{"no":4,"local_id":"50004","quid":"Q1000073684","section":"REASONING","topic":"Embedded Figures","question":{"en":"Select the image that embeds the following figure.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"वह छवि चुनिए जिसमें निम्नलिखित आकृति निहित है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"3","solution":{"en":"The parallelogram is formed in figure (C) by its two slanting lines with the top and bottom sides of the square.<br><br><b>Hence, the correct answer is option (3): Figure (3).</b>","hi":"समांतर चतुर्भुज आकृति (C) में दो तिरछी रेखाओं और वर्ग की ऊपरी व निचली भुजाओं से बनता है।<br><br><b>अतः सही उत्तर विकल्प (3): आकृति (3) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q4_opt4.jpg"]}}},{"no":5,"local_id":"50005","quid":"Q1000073685","section":"REASONING","topic":"Venn Diagrams","question":{"en":"Among 120 people, 80 like rock music, 50 like jazz, and 30 like both. How many people like neither? [SSC CGL 10/10/26 Shift 2]","hi":"120 लोगों में से 80 को रॉक संगीत, 50 को जैज़ और 30 को दोनों पसंद हैं। कितने लोगों को दोनों में से कोई भी पसंद नहीं है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"20"},"2":{"en":"10"},"3":{"en":"50"},"4":{"en":"5"}},"answer":"1","solution":{"en":"At least one = 80 + 50 − 30 = 100<br>Neither = 120 − 100 = 20<br><br><b>Hence, the correct answer is option (1): 20.</b>","hi":"कम से कम एक = 80 + 50 − 30 = 100<br>कोई नहीं = 120 − 100 = 20<br><br><b>अतः सही उत्तर विकल्प (1): 20 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":6,"local_id":"50006","quid":"Q1000073686","section":"REASONING","topic":"Venn Diagrams","question":{"en":"In a group of 40 children, 28 like Ice Cream, 18 like Cake, and 10 like both. How many like only Cake? [SSC CGL 10/10/26 Shift 2]","hi":"40 बच्चों के एक समूह में, 28 को आइसक्रीम, 18 को केक और 10 को दोनों पसंद हैं। कितनों को केवल केक पसंद है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"8"},"2":{"en":"10"},"3":{"en":"5"},"4":{"en":"6"}},"answer":"1","solution":{"en":"Only Cake = Cake − Both<br>= 18 − 10 = 8<br><br><b>Hence, the correct answer is option (1): 8.</b>","hi":"केवल केक = केक − दोनों<br>= 18 − 10 = 8<br><br><b>अतः सही उत्तर विकल्प (1): 8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":7,"local_id":"50007","quid":"Q1000073687","section":"REASONING","topic":"Miscellaneous","question":{"en":"Which of the following is the unit digit in the product of {(241)<sup>491</sup> × (435)<sup>317</sup> × (3364)<sup>1793</sup>}? [SSC CGL 10/10/26 Shift 2]","hi":"{(241)<sup>491</sup> × (435)<sup>317</sup> × (3364)<sup>1793</sup>} के गुणनफल में इकाई अंक निम्नलिखित में से कौन-सा है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"8"},"2":{"en":"7"},"3":{"en":"0"},"4":{"en":"3"}},"answer":"3","solution":{"en":"Unit digits: 1 (any power) = 1, 5 (any power) = 5, 4 (odd power) = 4<br>1 × 5 × 4 = 20 → unit digit 0<br><br><b>Hence, the correct answer is option (3): 0.</b>","hi":"इकाई अंक: 1 (किसी भी घात) = 1, 5 (किसी भी घात) = 5, 4 (विषम घात) = 4<br>1 × 5 × 4 = 20 → इकाई अंक 0<br><br><b>अतः सही उत्तर विकल्प (3): 0 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":8,"local_id":"50008","quid":"Q1000073688","section":"REASONING","topic":"Number Series","question":{"en":"Find the missing number in the following series:<br>9, 11, 16, 26, ?, 69 [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित श्रृंखला में लुप्त संख्या ज्ञात कीजिए:<br>9, 11, 16, 26, ?, 69 [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"43"},"2":{"en":"52"},"3":{"en":"48"},"4":{"en":"56"}},"answer":"1","solution":{"en":"Differences are 2, 5, 10, 17, 26 (i.e. n² + 1).<br>26 + 17 = 43, 43 + 26 = 69<br><br><b>Hence, the correct answer is option (1): 43.</b>","hi":"अंतर 2, 5, 10, 17, 26 हैं (अर्थात n² + 1)।<br>26 + 17 = 43, 43 + 26 = 69<br><br><b>अतः सही उत्तर विकल्प (1): 43 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":9,"local_id":"50009","quid":"Q1000073689","section":"REASONING","topic":"Order & Ranking","question":{"en":"Aditi is ranked 5th from the top and 20th from the bottom in a class. How many students are there in the class? [SSC CGL 10/10/26 Shift 2]","hi":"एक कक्षा में अदिति का स्थान ऊपर से 5वाँ और नीचे से 20वाँ है। कक्षा में कितने छात्र हैं? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"23"},"2":{"en":"24"},"3":{"en":"25"},"4":{"en":"26"}},"answer":"2","solution":{"en":"Total = Rank from top + Rank from bottom − 1<br>= 5 + 20 − 1 = 24<br><br><b>Hence, the correct answer is option (2): 24.</b>","hi":"कुल = ऊपर से स्थान + नीचे से स्थान − 1<br>= 5 + 20 − 1 = 24<br><br><b>अतः सही उत्तर विकल्प (2): 24 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":10,"local_id":"50010","quid":"Q1000073690","section":"REASONING","topic":"Mathematical Operations","question":{"en":"<b>If A means '+', B means '−', C means '×', and D means '÷', which of the following statement(s) is/are correct?</b><br><b>Statement I:</b> 12 C 4 D 2 A 6 = 30<br><b>Statement II:</b> 20 B 10 A 5 C 2 = 20 [SSC CGL 10/10/26 Shift 2]","hi":"<b>यदि A का अर्थ '+', B का अर्थ '−', C का अर्थ '×' और D का अर्थ '÷' है, तो निम्नलिखित में से कौन-सा/से कथन सही है/हैं?</b><br><b>कथन I:</b> 12 C 4 D 2 A 6 = 30<br><b>कथन II:</b> 20 B 10 A 5 C 2 = 20 [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Only I","hi":"केवल I"},"2":{"en":"Only II","hi":"केवल II"},"3":{"en":"Both I and II","hi":"I और II दोनों"},"4":{"en":"Neither I nor II","hi":"न तो I और न ही II"}},"answer":"3","solution":{"en":"I: 12 × 4 ÷ 2 + 6 = 24 + 6 = 30 ✓<br>II: 20 − 10 + 5 × 2 = 10 + 10 = 20 ✓<br><br><b>Hence, the correct answer is option (3): Both I and II.</b>","hi":"I: 12 × 4 ÷ 2 + 6 = 24 + 6 = 30 ✓<br>II: 20 − 10 + 5 × 2 = 10 + 10 = 20 ✓<br><br><b>अतः सही उत्तर विकल्प (3): I और II दोनों है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":11,"local_id":"50011","quid":"Q1000073691","section":"REASONING","topic":"Figure Completing","question":{"en":"Complete the pattern in fig. (X) by selecting one of the figures from the four alternatives:<br>Figure (X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"चार विकल्पों में से एक आकृति चुनकर आकृति (X) के पैटर्न को पूरा कीजिए:<br>आकृति (X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"The missing strip must continue the black and white bands and the Y-shaped lines of the adjoining parts.<br>Only figure (D) matches.<br><br><b>Hence, the correct answer is option (4): Figure (4).</b>","hi":"लुप्त पट्टी को आसपास के भागों की काली-सफ़ेद पट्टियों और Y-आकार की रेखाओं को आगे बढ़ाना चाहिए।<br>केवल आकृति (D) मेल खाती है।<br><br><b>अतः सही उत्तर विकल्प (4): आकृति (4) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q11_opt4.jpg"]}}},{"no":12,"local_id":"50012","quid":"Q1000073692","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"In the following question a statement is given followed by some assumptions. Read the assumptions carefully and choose the appropriate option.<br><b>Statement:</b><br>Please check the weather forecast before organizing the outdoor event.<br><b>Assumptions:</b><br>I. Weather conditions can affect the success of the event.<br>II. It is desirable for the event to run smoothly. [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में एक कथन और उसके बाद कुछ पूर्वधारणाएँ दी गई हैं। पूर्वधारणाओं को ध्यान से पढ़िए और उपयुक्त विकल्प चुनिए।<br><b>कथन:</b><br>कृपया बाहरी कार्यक्रम आयोजित करने से पहले मौसम का पूर्वानुमान देख लें।<br><b>पूर्वधारणाएँ:</b><br>I. मौसम की स्थिति कार्यक्रम की सफलता को प्रभावित कर सकती है।<br>II. कार्यक्रम का सुचारु रूप से चलना वांछनीय है। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Only I is implicit.","hi":"केवल I निहित है।"},"2":{"en":"Only II is implicit.","hi":"केवल II निहित है।"},"3":{"en":"Neither I nor II is implicit.","hi":"न तो I और न ही II निहित है।"},"4":{"en":"Both I and II are implicit.","hi":"I और II दोनों निहित हैं।"}},"answer":"4","solution":{"en":"Checking the forecast assumes weather can affect the event (I).<br>It also assumes that a smooth event is desired (II).<br><br><b>Hence, the correct answer is option (4): Both I and II are implicit.</b>","hi":"पूर्वानुमान देखना यह मानता है कि मौसम कार्यक्रम को प्रभावित कर सकता है (I)।<br>यह भी मानता है कि कार्यक्रम का सुचारु चलना वांछनीय है (II)।<br><br><b>अतः सही उत्तर विकल्प (4): I और II दोनों निहित हैं। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":13,"local_id":"50013","quid":"Q1000073693","section":"REASONING","topic":"Paper Folding, Cutting & Mirror/Water Images","question":{"en":"If a mirror is placed on the line XY, which figure will be the mirror image of the question figure?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"यदि रेखा XY पर दर्पण रखा जाए, तो कौन-सी आकृति प्रश्न आकृति का दर्पण प्रतिबिंब होगी?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"The mirror is vertical on the right, so the order H 2 J 4 K 6 is reversed and each character is laterally inverted.<br>This gives figure (D).<br><br><b>Hence, the correct answer is option (4): Figure (4).</b>","hi":"दर्पण दाईं ओर ऊर्ध्वाधर है, अतः क्रम H 2 J 4 K 6 उलट जाता है और प्रत्येक अक्षर पार्श्व रूप से उलट जाता है।<br>इससे आकृति (D) मिलती है।<br><br><b>अतः सही उत्तर विकल्प (4): आकृति (4) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q13_opt4.jpg"]}}},{"no":14,"local_id":"50014","quid":"Q1000073694","section":"REASONING","topic":"Matrix","question":{"en":"Which of the following rows/columns are connected/related with each other in some way?<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">Rows</td><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">V</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">1</td><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">42</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">26</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">56</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">3</td><td style=\"border:1px solid #888;padding:3px 6px\">15</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">15</td><td style=\"border:1px solid #888;padding:3px 6px\">35</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">36</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">63</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">20</td><td style=\"border:1px solid #888;padding:3px 6px\">40</td><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">30</td><td style=\"border:1px solid #888;padding:3px 6px\">70</td></tr></table> [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सी पंक्तियाँ/स्तंभ किसी प्रकार एक-दूसरे से जुड़े/संबंधित हैं?<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">पंक्ति</td><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">V</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">1</td><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">42</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">26</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">56</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">3</td><td style=\"border:1px solid #888;padding:3px 6px\">15</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">15</td><td style=\"border:1px solid #888;padding:3px 6px\">35</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">36</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">63</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">20</td><td style=\"border:1px solid #888;padding:3px 6px\">40</td><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">30</td><td style=\"border:1px solid #888;padding:3px 6px\">70</td></tr></table> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Columns I, II and IV","hi":"स्तंभ I, II और IV"},"2":{"en":"Columns II, III and IV","hi":"स्तंभ II, III और IV"},"3":{"en":"Columns III, IV and V","hi":"स्तंभ III, IV और V"},"4":{"en":"Columns I, III and V","hi":"स्तंभ I, III और V"}},"answer":"3","solution":{"en":"In every row: Column IV = 3 × Column III and Column V = 7 × Column III.<br>e.g. 6, 18, 42 and 8, 24, 56<br><br><b>Hence, the correct answer is option (3): Columns III, IV and V.</b>","hi":"हर पंक्ति में: स्तंभ IV = 3 × स्तंभ III और स्तंभ V = 7 × स्तंभ III<br>जैसे 6, 18, 42 और 8, 24, 56<br><br><b>अतः सही उत्तर विकल्प (3): स्तंभ III, IV और V है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":15,"local_id":"50015","quid":"Q1000073695","section":"REASONING","topic":"Situational Judgement","question":{"en":"Why do highly cohesive groups sometimes make flawed or poor decisions? [SSC CGL 10/10/26 Shift 2]","hi":"अत्यधिक संगठित (cohesive) समूह कभी-कभी त्रुटिपूर्ण या खराब निर्णय क्यों लेते हैं? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"The pressure for conformity and agreement suppresses dissenting viewpoints.","hi":"अनुरूपता और सहमति का दबाव असहमति वाले विचारों को दबा देता है।"},"2":{"en":"They experience chronic conflicts that stall the decision-making process.","hi":"उनमें लगातार संघर्ष होते हैं जो निर्णय प्रक्रिया को रोक देते हैं।"},"3":{"en":"They lack the cognitive intelligence needed to solve complex problems.","hi":"उनमें जटिल समस्याओं को हल करने के लिए आवश्यक संज्ञानात्मक बुद्धि की कमी होती है।"},"4":{"en":"They waste excessive time on over-communicating minor details.","hi":"वे छोटी-छोटी बातों पर अत्यधिक संवाद में बहुत समय बर्बाद करते हैं।"}},"answer":"1","solution":{"en":"In very close groups, members avoid disagreeing to keep harmony (groupthink).<br>Different views are suppressed, so poor decisions go unchallenged.<br><br><b>Hence, the correct answer is option (1): The pressure for conformity and agreement suppresses dissenting viewpoints.</b>","hi":"बहुत घनिष्ठ समूहों में सदस्य सामंजस्य बनाए रखने के लिए असहमति से बचते हैं (ग्रुपथिंक)।<br>अलग विचार दब जाते हैं, अतः खराब निर्णयों पर कोई सवाल नहीं उठता।<br><br><b>अतः सही उत्तर विकल्प (1): अनुरूपता और सहमति का दबाव असहमति वाले विचारों को दबा देता है। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":16,"local_id":"50016","quid":"Q1000073696","section":"REASONING","topic":"Situational Judgement","question":{"en":"Direction:<br>Select the most logical decision.<br><br>A technology firm develops an innovation that could significantly increase efficiency but may also reduce the need for certain job roles over time. [SSC CGL 10/10/26 Shift 2]","hi":"निर्देश:<br>सबसे तार्किक निर्णय चुनिए।<br><br>एक प्रौद्योगिकी फ़र्म एक नवाचार विकसित करती है जो दक्षता को काफ़ी बढ़ा सकता है, लेकिन समय के साथ कुछ पदों की आवश्यकता को भी कम कर सकता है। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Implement the innovation immediately without considering workforce implications.","hi":"कार्यबल पर प्रभावों पर विचार किए बिना नवाचार को तुरंत लागू करना।"},"2":{"en":"Reject the innovation entirely because workforce changes may occur eventually.","hi":"नवाचार को पूरी तरह अस्वीकार करना क्योंकि अंततः कार्यबल में बदलाव हो सकते हैं।"},"3":{"en":"Introduce the innovation gradually while planning workforce transition measures.","hi":"कार्यबल संक्रमण के उपायों की योजना बनाते हुए नवाचार को धीरे-धीरे लागू करना।"},"4":{"en":"Delay implementation permanently until technological alternatives become available.","hi":"तकनीकी विकल्प उपलब्ध होने तक कार्यान्वयन को स्थायी रूप से टाल देना।"}},"answer":"3","solution":{"en":"Gradual adoption keeps the efficiency gain and also protects employees through transition planning.<br>The other options ignore either the benefit or the workforce.<br><br><b>Hence, the correct answer is option (3): Introduce the innovation gradually while planning workforce transition measures.</b>","hi":"क्रमिक अपनाने से दक्षता का लाभ भी मिलता है और संक्रमण योजना से कर्मचारियों की रक्षा भी होती है।<br>अन्य विकल्प या तो लाभ या कार्यबल की अनदेखी करते हैं।<br><br><b>अतः सही उत्तर विकल्प (3): कार्यबल संक्रमण के उपायों की योजना बनाते हुए नवाचार को धीरे-धीरे लागू करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":17,"local_id":"50017","quid":"Q1000073697","section":"REASONING","topic":"Odd One Out","question":{"en":"Identify the image from the given images that does NOT belong to the group.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q17.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"दी गई छवियों में से वह छवि पहचानिए जो समूह से संबंधित नहीं है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q17.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"C"},"2":{"en":"A"},"3":{"en":"B"},"4":{"en":"D"}},"answer":"1","solution":{"en":"In (A), (B) and (D) both shapes have notched (V-cut) ends.<br>In (C) the shaded lower shape has a pointed end, so it is different.<br><br><b>Hence, the correct answer is option (1): C.</b>","hi":"(A), (B) और (D) में दोनों आकृतियों के सिरे V-कट वाले हैं।<br>(C) में छायांकित निचली आकृति का सिरा नुकीला है, अतः यह भिन्न है।<br><br><b>अतः सही उत्तर विकल्प (1): C है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q17.jpg"]}},{"no":18,"local_id":"50018","quid":"Q1000073698","section":"REASONING","topic":"Odd One Out","question":{"en":"Point out the figure that does NOT match the others.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q18.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"वह आकृति बताइए जो अन्य से मेल नहीं खाती।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q18.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"A"},"2":{"en":"B"},"3":{"en":"C"},"4":{"en":"D"}},"answer":"4","solution":{"en":"(A), (B) and (C) are rotations of the same arrangement of the black, white and grey circles.<br>In (D) the order of the colours is different.<br><br><b>Hence, the correct answer is option (4): D.</b>","hi":"(A), (B) और (C) काले, सफ़ेद और धूसर वृत्तों की एक ही व्यवस्था के घुमाए हुए रूप हैं।<br>(D) में रंगों का क्रम भिन्न है।<br><br><b>अतः सही उत्तर विकल्प (4): D है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q18.jpg"]}},{"no":19,"local_id":"50019","quid":"Q1000073699","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"In the following question, there is a specific relationship between the first two figures. Establish a similar relationship between the third and fourth figures by selecting a suitable figure from the given Answer Figures to replace the question mark (?).<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में, पहली दो आकृतियों के बीच एक विशेष संबंध है। दी गई उत्तर आकृतियों में से उपयुक्त आकृति चुनकर प्रश्न चिह्न (?) के स्थान पर रखिए ताकि तीसरी और चौथी आकृति के बीच भी वैसा ही संबंध स्थापित हो।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"3"},"3":{"en":"2"},"4":{"en":"4"}},"answer":"3","solution":{"en":"From A to B the figure is turned upside down and the shading of the end shapes is interchanged.<br>Applying the same change to C gives answer figure (2).<br><br><b>Hence, the correct answer is option (3): 2.</b>","hi":"A से B में आकृति उलट दी जाती है और सिरों की आकृतियों की छायांकन आपस में बदल जाती है।<br>C पर यही बदलाव करने से उत्तर आकृति (2) मिलती है।<br><br><b>अतः सही उत्तर विकल्प (3): 2 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q19.jpg"]}},{"no":20,"local_id":"50020","quid":"Q1000073700","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"In the following question, there is a specific relationship between the first two figures. Establish a similar relationship between the third and fourth figures by selecting a suitable figure from the given Answer Figures to replace the question mark (?).<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में, पहली दो आकृतियों के बीच एक विशेष संबंध है। दी गई उत्तर आकृतियों में से उपयुक्त आकृति चुनकर प्रश्न चिह्न (?) के स्थान पर रखिए ताकि तीसरी और चौथी आकृति के बीच भी वैसा ही संबंध स्थापित हो।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"4"},"3":{"en":"3"},"4":{"en":"5"}},"answer":"2","solution":{"en":"The second figure is the first one turned upside down (vertical flip).<br>Flipping the third figure the same way gives answer figure (4).<br><br><b>Hence, the correct answer is option (2): 4.</b>","hi":"दूसरी आकृति पहली आकृति का उलटा (ऊर्ध्वाधर रूप से पलटा) रूप है।<br>तीसरी आकृति को उसी तरह पलटने पर उत्तर आकृति (4) मिलती है।<br><br><b>अतः सही उत्तर विकल्प (2): 4 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q20.jpg"]}},{"no":21,"local_id":"50021","quid":"Q1000073701","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Fill in the blanks (_) using one of the following four options such that the series follows a specific pattern in the given order.<br>_ bb _ a _ bd _ b _ d [SSC CGL 10/10/26 Shift 2]","hi":"दिए गए चार विकल्पों में से एक का प्रयोग करके रिक्त स्थानों (_) को इस प्रकार भरिए कि श्रृंखला दिए गए क्रम में एक विशेष पैटर्न का अनुसरण करे।<br>_ bb _ a _ bd _ b _ d [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"abdba"},"2":{"en":"adbaa"},"3":{"en":"dbabb"},"4":{"en":"adbab"}},"answer":"4","solution":{"en":"Filling a, d, b, a, b gives:<br>abbd / abbd / abbd<br>The unit 'abbd' repeats.<br><br><b>Hence, the correct answer is option (4): adbab.</b>","hi":"a, d, b, a, b भरने पर:<br>abbd / abbd / abbd<br>इकाई 'abbd' दोहराई जाती है।<br><br><b>अतः सही उत्तर विकल्प (4): adbab है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":22,"local_id":"50022","quid":"Q1000073702","section":"REASONING","topic":"Embedded Figures","question":{"en":"Carefully observe Figure (X) and identify the answer figure in which Figure (X) is embedded in the same or rotated form.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q22.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"आकृति (X) को ध्यान से देखिए और वह उत्तर आकृति पहचानिए जिसमें आकृति (X) समान या घुमाए हुए रूप में निहित है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q22.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"2"},"3":{"en":"4"},"4":{"en":"3"}},"answer":"4","solution":{"en":"Figure (X) appears in figure (3) in rotated form.<br><br><b>Hence, the correct answer is option (4): 3.</b>","hi":"आकृति (X), आकृति (3) में घुमाए हुए रूप में दिखाई देती है।<br><br><b>अतः सही उत्तर विकल्प (4): 3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q22.jpg"]}},{"no":23,"local_id":"50023","quid":"Q1000073703","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"Select a figure from amongst the alternatives that will continue the same series as established by the problem figures.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"विकल्पों में से वह आकृति चुनिए जो प्रश्न आकृतियों द्वारा स्थापित श्रृंखला को आगे बढ़ाएगी।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"The central figure turns 90° clockwise at each step, and the two stars move to the other corners in turn.<br>The next figure is (D).<br><br><b>Hence, the correct answer is option (4): Figure (4).</b>","hi":"केंद्रीय आकृति हर चरण में 90° दक्षिणावर्त घूमती है, और दोनों तारे बारी-बारी से दूसरे कोनों में जाते हैं।<br>अगली आकृति (D) है।<br><br><b>अतः सही उत्तर विकल्प (4): आकृति (4) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q23_opt4.jpg"]}}},{"no":24,"local_id":"50024","quid":"Q1000073704","section":"REASONING","topic":"Odd One Out","question":{"en":"Choose the letter pair that does not belong to the group. [SSC CGL 10/10/26 Shift 2]","hi":"वह अक्षर-युग्म चुनिए जो समूह से संबंधित नहीं है। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"AZ"},"2":{"en":"BY"},"3":{"en":"CX"},"4":{"en":"DV"}},"answer":"4","solution":{"en":"AZ, BY, CX are opposite letter pairs (positions add to 27).<br>The opposite of D is W, not V, so DV is different.<br><br><b>Hence, the correct answer is option (4): DV.</b>","hi":"AZ, BY, CX विपरीत अक्षर-युग्म हैं (स्थानों का योग 27)।<br>D का विपरीत W है, V नहीं, अतः DV भिन्न है।<br><br><b>अतः सही उत्तर विकल्प (4): DV है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":25,"local_id":"50025","quid":"Q1000073705","section":"REASONING","topic":"Paper Folding, Cutting & Mirror/Water Images","question":{"en":"A piece of paper is folded and punched as shown below. From the given answer figures indicate how it will appear when opened?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q25.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]","hi":"कागज़ के एक टुकड़े को नीचे दिखाए अनुसार मोड़कर छेद किया गया है। दी गई उत्तर आकृतियों में से बताइए कि खोलने पर यह कैसा दिखाई देगा?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q25.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"A"},"2":{"en":"B"},"3":{"en":"C"},"4":{"en":"D"}},"answer":"4","solution":{"en":"Unfold in reverse order; the punched shape is mirrored across each fold line.<br>So the four shapes appear as mirror images of each other, as in figure (D).<br><br><b>Hence, the correct answer is option (4): D.</b>","hi":"उल्टे क्रम में खोलें; छेद की आकृति हर मोड़ रेखा के पार प्रतिबिंबित होती है।<br>अतः चारों आकृतियाँ एक-दूसरे का दर्पण प्रतिबिंब होती हैं, जैसा आकृति (D) में है।<br><br><b>अतः सही उत्तर विकल्प (4): D है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q25.jpg"]}}]},"GK":{"seconds":900,"questions":[{"no":26,"local_id":"50026","quid":"Q1000073706","section":"GK","topic":"Economics: Monetary Policy","question":{"en":"In money supply, M3 refers to which of the following? [SSC CGL 10/10/26 Shift 2]","hi":"मुद्रा आपूर्ति में, M3 निम्नलिखित में से किसे संदर्भित करता है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"M1 + savings deposits with post office savings banks","hi":"M1 + डाकघर बचत बैंकों की बचत जमाएँ"},"2":{"en":"M1 + net time deposits of banks","hi":"M1 + बैंकों की शुद्ध सावधि जमाएँ"},"3":{"en":"M1 - savings deposits with post office savings banks","hi":"M1 - डाकघर बचत बैंकों की बचत जमाएँ"},"4":{"en":"M1 - net time deposits of banks","hi":"M1 - बैंकों की शुद्ध सावधि जमाएँ"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – M1 + savings deposits with post office savings banks</b><br>In India’s money supply measures, <b>M3 = M1 + net time deposits with banks</b>, while <b>M1 + savings deposits with post office savings banks</b> is the definition of <b>M2</b>, which is the measure this question asks about.<br><br><br><b><u>Important Points:</u></b><br>• <b>M1 = currency with the public + demand deposits + other deposits with the RBI</b>; it is the most liquid measure and is called narrow money.<br>• The series runs <b>M1 → M2 → M3 → M4</b>, with each successive measure adding less liquid assets, so <b>M1 is the most liquid and M4 the least</b>.<br>• <b>M3</b> is called <b>broad money</b> and is the most widely used measure of money supply, while <b>M4 = M3 + total post office deposits</b>.<br>• Money supply is compiled and published by the <b>Reserve Bank of India</b>, and an increase in M3 beyond the growth of real output is a common indicator of inflationary pressure.","hi":"<b>सही उत्तर: विकल्प (1) – M1 + डाकघर बचत बैंकों की बचत जमाएँ</b><br>भारत में मुद्रा आपूर्ति के मापों में <b>M3 = M1 + बैंकों में निवल सावधि जमा</b> होता है, जबकि <b>M1 + डाकघर बचत बैंकों में बचत जमा</b> <b>M2</b> की परिभाषा है, और प्रश्न इसी माप की ओर संकेत करता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>M1 = जनता के पास मुद्रा + मांग जमा + भारतीय रिज़र्व बैंक के पास अन्य जमा</b>; यह सर्वाधिक तरल माप है और इसे संकुचित मुद्रा (Narrow money) कहा जाता है।<br>• यह श्रृंखला <b>M1 → M2 → M3 → M4</b> है, जिसमें प्रत्येक अगला माप कम तरल परिसंपत्तियाँ जोड़ता है, अतः <b>M1 सर्वाधिक तरल तथा M4 सर्वाधिक अल्प तरल</b> है।<br>• <b>M3</b> को <b>व्यापक मुद्रा (Broad money)</b> कहा जाता है और यह सर्वाधिक प्रयुक्त माप है, जबकि <b>M4 = M3 + डाकघर की कुल जमा</b>।<br>• मुद्रा आपूर्ति का संकलन व प्रकाशन <b>भारतीय रिज़र्व बैंक</b> करता है; वास्तविक उत्पादन की वृद्धि से अधिक M3 वृद्धि मुद्रास्फीतिक दबाव का सामान्य संकेतक है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":27,"local_id":"50027","quid":"Q1000073707","section":"GK","topic":"Medieval History: Bhakti and Sufi Movements","question":{"en":"The Bhakti saint who promoted unity between Hindus and Muslims and was a disciple of Ramananda: [SSC CGL 10/10/26 Shift 2]","hi":"वह भक्ति संत, जिसने हिंदुओं और मुसलमानों के बीच एकता को बढ़ावा दिया तथा जो रामानंद के शिष्य थे: [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Surdas","hi":"सूरदास"},"2":{"en":"Kabir","hi":"कबीर"},"3":{"en":"Mirabai","hi":"मीराबाई"},"4":{"en":"Tulsidas","hi":"तुलसीदास"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Kabir</b><br>Kabir was a nirguna bhakti saint of the 15th century and a disciple of <b>Ramananda</b>. He attacked idol worship, rituals and the caste system, and preached the unity of Hindus and Muslims through his dohas and padas collected in the <b>Bijak</b>.<br><br><br><b><u>Important Points:</u></b><br>• Kabir is believed to have been born at <b>Varanasi (Kabir Chaura)</b> and his verses are also included in the <b>Guru Granth Sahib</b>.<br>• Surdas, Mirabai and Tulsidas belonged to the <b>saguna</b> (form-worshipping) stream — Surdas and Tulsidas were devotees of Rama and Mirabai of Krishna.<br>• Ramananda was a 14th-century Vaishnava saint of Varanasi who preached in the local language and is said to have been the guru of Kabir, Ravidas, Dhanna and Sena.<br>• Other nirguna saints were Raidas and Dadu, while the Sufi movement’s parallel idea of unity was expressed by the Chishti silsilah.","hi":"<b>सही उत्तर: विकल्प (2) – कबीर</b><br>कबीर 15वीं शताब्दी के निर्गुण भक्ति संत तथा रामानंद के शिष्य थे। उन्होंने मूर्तिपूजा, कर्मकांड और जाति-प्रथा की कड़ी आलोचना की तथा अपने दोहों व पदों (जो बीजक में संकलित हैं) के माध्यम से हिंदुओं और मुसलमानों की एकता का उपदेश दिया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• कबीर का जन्म वाराणसी (कबीर चौरा) में माना जाता है तथा उनकी रचनाएँ गुरु ग्रंथ साहिब में भी सम्मिलित हैं।<br>• सूरदास, मीराबाई और तुलसीदास सगुण शाखा के थे — सूरदास व तुलसीदास राम के तथा मीराबाई कृष्ण की भक्त थीं।<br>• रामानंद 14वीं शताब्दी के वाराणसी के वैष्णव संत थे, जिन्होंने लोकभाषा में उपदेश दिया; कबीर, रैदास, धन्ना तथा सेना को उनका शिष्य माना जाता है।<br>• अन्य निर्गुण संत रैदास व दादू थे, जबकि सूफी आंदोलन में एकता का समान विचार चिश्ती सिलसिले ने व्यक्त किया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":28,"local_id":"50028","quid":"Q1000073708","section":"GK","topic":"Current Affairs: International News","question":{"en":"IMEC (India-Middle East-Europe Economic Corridor) aims to significantly reduce: [SSC CGL 10/10/26 Shift 2]","hi":"IMEC (भारत-मध्य पूर्व-यूरोप आर्थिक गलियारा) का उद्देश्य निम्नलिखित में से किसमें उल्लेखनीय कमी लाना है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Cultural exchanges","hi":"सांस्कृतिक आदान-प्रदान"},"2":{"en":"Transit times for goods between Asia and Europe","hi":"एशिया और यूरोप के बीच वस्तुओं के पारगमन समय"},"3":{"en":"International tourism","hi":"अंतर्राष्ट्रीय पर्यटन"},"4":{"en":"Military spending","hi":"सैन्य व्यय"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Transit times for goods between Asia and Europe</b><br>The India-Middle East-Europe Economic Corridor (IMEC) is planned to cut the transit time and cost of goods moving between Asia, the Gulf and Europe by linking ports and rail routes through the UAE, Saudi Arabia, Jordan and Israel.<br><br><br><b><u>Important Points:</u></b><br>• IMEC was announced at the <b>G20 Summit in New Delhi (September 2023)</b> by India, the USA, Saudi Arabia, the UAE, the EU, France, Germany and Italy.<br>• It has two parts — the <b>East Corridor</b> (India to the Arabian Gulf) and the <b>Northern Corridor</b> (Gulf to Europe) — supported by rail, electricity, hydrogen and data cables.<br>• It is seen as a rival/complement to China’s <b>Belt and Road Initiative (BRI)</b> and to the Suez Canal route.<br>• The <b>IMO (India-Middle East-Europe Economic Corridor) memorandum</b> was signed during the G20 Leaders’ Summit, and the India-Middle East-Europe corridor is also called the \"Spice Route\" project.","hi":"<b>सही उत्तर: विकल्प (2) – एशिया और यूरोप के बीच वस्तुओं के पारगमन समय</b><br>भारत-मध्य पूर्व-यूरोप आर्थिक गलियारा (IMEC) संयुक्त अरब अमीरात, सऊदी अरब, जॉर्डन तथा इज़रायल से होकर बंदरगाहों व रेल मार्गों को जोड़कर एशिया, खाड़ी और यूरोप के बीच वस्तुओं के पारगमन समय तथा लागत को घटाने की योजना है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• IMEC की घोषणा सितंबर 2023 में नई दिल्ली के G20 शिखर सम्मेलन में भारत, अमेरिका, सऊदी अरब, UAE, यूरोपीय संघ, फ्रांस, जर्मनी और इटली ने की।<br>• इसके दो भाग हैं — पूर्वी गलियारा (भारत से अरब की खाड़ी) तथा उत्तरी गलियारा (खाड़ी से यूरोप), जिसमें रेल, विद्युत, हाइड्रोजन व डेटा केबल शामिल हैं।<br>• इसे चीन की बेल्ट एंड रोड पहल (BRI) तथा स्वेज नहर मार्ग का प्रतिस्पर्धी/पूरक माना जाता है।<br>• जी20 शिखर सम्मेलन के दौरान IMEC पर सहमति-पत्र पर हस्ताक्षर हुए; इसे \"मसाला मार्ग\" (Spice Route) परियोजना भी कहा जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":29,"local_id":"50029","quid":"Q1000073709","section":"GK","topic":"Static GK: Government Schemes","question":{"en":"Which government initiative aims to make India a digitally empowered society and knowledge economy? [SSC CGL 10/10/26 Shift 2]","hi":"कौन-सी सरकारी पहल भारत को डिजिटल रूप से सशक्त समाज और ज्ञान अर्थव्यवस्था बनाने का लक्ष्य रखती है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Make in India","hi":"मेक इन इंडिया"},"2":{"en":"Skill India Mission","hi":"स्किल इंडिया मिशन"},"3":{"en":"Digital India","hi":"डिजिटल इंडिया"},"4":{"en":"Smart Cities Mission","hi":"स्मार्ट सिटीज मिशन"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Digital India</b><br>Digital India, launched on 1 July 2015, aims to make India a <b>digitally empowered society and knowledge economy</b> by providing digital infrastructure as a core utility, governance and services on demand, and digital literacy.<br><br><br><b><u>Important Points:</u></b><br>• Digital India has three vision areas — digital infrastructure as a utility to every citizen, governance and services on demand, and digital empowerment of citizens.<br>• Its key projects are Aadhaar, BharatNet, DigiLocker, UMANG, BHIM-UPI, e-Hospital and PM-WANI.<br>• <b>Make in India</b> (25 September 2014) promotes manufacturing, <b>Smart Cities Mission</b> (25 June 2015) develops 100 smart cities, and Skill India (15 July 2015) provides skill training.<br>• India’s UPI is now the world’s largest real-time digital payments system, and Digital India is implemented by the Ministry of Electronics and Information Technology (MeitY).","hi":"<b>सही उत्तर: विकल्प (3) – डिजिटल इंडिया</b><br>1 जुलाई 2015 को शुरू किए गए डिजिटल इंडिया का लक्ष्य डिजिटल अवसंरचना को मूल उपयोगिता बनाकर, मांग आधारित शासन व सेवाएँ उपलब्ध कराकर तथा डिजिटल साक्षरता बढ़ाकर भारत को डिजिटल रूप से सशक्त समाज और ज्ञान अर्थव्यवस्था बनाना है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• डिजिटल इंडिया के तीन दृष्टिकोण क्षेत्र हैं — प्रत्येक नागरिक के लिए उपयोगिता के रूप में डिजिटल अवसंरचना, मांग पर शासन एवं सेवाएँ तथा नागरिकों का डिजिटल सशक्तीकरण।<br>• इसकी प्रमुख परियोजनाएँ आधार, भारतनेट, डिजिलॉकर, UMANG, BHIM-UPI, ई-हॉस्पिटल तथा PM-WANI हैं।<br>• मेक इन इंडिया (25 सितंबर 2014) विनिर्माण को बढ़ावा देता है, स्मार्ट सिटीज मिशन (25 जून 2015) 100 स्मार्ट शहर विकसित करता है तथा स्किल इंडिया (15 जुलाई 2015) कौशल प्रशिक्षण देता है।<br>• भारत का UPI अब विश्व की सबसे बड़ी रीयल-टाइम डिजिटल भुगतान प्रणाली है; डिजिटल इंडिया इलेक्ट्रॉनिकी एवं सूचना प्रौद्योगिकी मंत्रालय (MeitY) द्वारा क्रियान्वित किया जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":30,"local_id":"50030","quid":"Q1000073710","section":"GK","topic":"Static GK: Government Schemes","question":{"en":"The \"Stand-Up India Scheme\" has a specific focus on promoting entrepreneurship among which of the following groups? [SSC CGL 10/10/26 Shift 2]","hi":"\"स्टैंड-अप इंडिया योजना\" निम्नलिखित में से किस वर्ग के बीच उद्यमशीलता को बढ़ावा देने पर विशेष ध्यान केंद्रित करती है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Senior citizens and ex-servicemen.","hi":"वरिष्ठ नागरिक और भूतपूर्व सैनिक।"},"2":{"en":"Women entrepreneurs and entrepreneurs from Scheduled Castes (SC) and Scheduled Tribes (ST) communities.","hi":"महिला उद्यमी तथा अनुसूचित जाति (SC) और अनुसूचित जनजाति (ST) समुदायों के उद्यमी।"},"3":{"en":"Students pursuing higher education in technical fields.","hi":"तकनीकी क्षेत्रों में उच्च शिक्षा प्राप्त कर रहे विद्यार्थी।"},"4":{"en":"Small and marginal farmers.","hi":"लघु और सीमांत किसान।"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Women entrepreneurs and entrepreneurs from Scheduled Castes (SC) and Scheduled Tribes (ST) communities.</b><br>Stand-Up India, launched on 5 April 2016, provides composite loans of ₹10 lakh to ₹1 crore to at least <b>one SC/ST entrepreneur and one woman entrepreneur per bank branch</b> for setting up greenfield enterprises in manufacturing, services, trading or the agriculture-allied sector.<br><br><br><b><u>Important Points:</u></b><br>• The loan is a composite loan (term loan plus working capital) with a repayment period of up to 7 years and a moratorium of up to 18 months.<br>• The scheme is implemented by the Department of Financial Services through scheduled commercial banks, and loans are covered by the <b>Credit Guarantee Scheme for Stand-Up India</b>.<br>• It works together with <b>MUDRA</b> (funding the unfunded) and Start-up India (16 January 2016) to build a start-up ecosystem.<br>• The scheme was announced by the Prime Minister in the <b>2015 Independence Day speech</b> and launched in 2016.","hi":"<b>सही उत्तर: विकल्प (2) – महिला उद्यमी तथा अनुसूचित जाति (SC) और अनुसूचित जनजाति (ST) समुदायों के उद्यमी।</b><br>5 अप्रैल 2016 को शुरू हुई स्टैंड-अप इंडिया योजना विनिर्माण, सेवा, व्यापार या कृषि-संबद्ध क्षेत्र में नए (ग्रीनफील्ड) उद्यम स्थापित करने हेतु <b>प्रत्येक बैंक शाखा में कम से कम एक SC/ST उद्यमी तथा एक महिला उद्यमी</b> को ₹10 लाख से ₹1 करोड़ तक का मिश्रित ऋण देती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह मिश्रित ऋण (मियादी ऋण सहित कार्यशील पूँजी) है, जिसकी चुकौती अवधि 7 वर्ष तक तथा किश्तों में छूट (moratorium) 18 माह तक होती है।<br>• योजना वित्तीय सेवाएँ विभाग द्वारा अनुसूचित वाणिज्यिक बैंकों के माध्यम से लागू की जाती है और ऋण स्टैंड-अप इंडिया हेतु ऋण गारंटी योजना के अंतर्गत आते हैं।<br>• यह <b>मुद्रा</b> (MUDRA) तथा स्टार्ट-अप इंडिया (16 जनवरी 2016) के साथ मिलकर स्टार्ट-अप पारिस्थितिकी तंत्र बनाती है।<br>• इस योजना की घोषणा प्रधानमंत्री ने 2015 के स्वतंत्रता दिवस भाषण में की और इसे 2016 में शुरू किया गया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":31,"local_id":"50031","quid":"Q1000073711","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"The first-ever Ranji Trophy final in 1935 was held in which city? [SSC CGL 10/10/26 Shift 2]","hi":"1935 में पहला रणजी ट्रॉफी फाइनल किस शहर में खेला गया था? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Mumbai","hi":"मुंबई"},"2":{"en":"Kolkata","hi":"कोलकाता"},"3":{"en":"New Delhi","hi":"नई दिल्ली"},"4":{"en":"Hyderabad","hi":"हैदराबाद"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Mumbai</b><br>The first Ranji Trophy final was played in 1935 at the Bombay Gymkhana in Mumbai, where Bombay defeated Northern India to win the maiden title. Mumbai (formerly Bombay) remains the most successful team in the tournament.<br><br><br><b><u>Important Points:</u></b><br>• The Ranji Trophy is India’s premier first-class cricket championship, named after <b>K.S. Ranjitsinhji</b> and started in 1934–35.<br>• Mumbai has won the Ranji Trophy a record <b>42 times</b>, followed by Karnataka and Delhi.<br>• The tournament is organised by the <b>BCCI</b>, which was founded in 1928 with headquarters at the Cricket Centre, Mumbai.<br>• Until 2016 the final of the Ranji Trophy was often held at the <b>Wankhede Stadium</b>; the 1935 final at Bombay Gymkhana is the first in the trophy’s history.","hi":"<b>सही उत्तर: विकल्प (1) – मुंबई</b><br>पहला रणजी ट्रॉफी फाइनल 1935 में मुंबई के बॉम्बे जिमखाना में खेला गया, जिसमें बॉम्बे ने नॉर्दर्न इंडिया को हराकर पहला खिताब जीता। मुंबई (पूर्व में बॉम्बे) आज भी इस टूर्नामेंट की सर्वाधिक सफल टीम है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• रणजी ट्रॉफी भारत की प्रमुख प्रथम श्रेणी क्रिकेट चैंपियनशिप है, जिसका नाम के.एस. रणजीतसिंहजी के नाम पर रखा गया और यह 1934–35 में शुरू हुई।<br>• मुंबई ने रिकॉर्ड 42 बार रणजी ट्रॉफी जीती है, उसके बाद कर्नाटक और दिल्ली का स्थान है।<br>• यह टूर्नामेंट बीसीसीआई द्वारा आयोजित होता है, जिसकी स्थापना 1928 में हुई; इसका मुख्यालय क्रिकेट सेंटर, मुंबई में है।<br>• 2016 तक रणजी ट्रॉफी का फाइनल अक्सर वानखेड़े स्टेडियम में होता था; 1935 का बॉम्बे जिमखाना फाइनल ट्रॉफी के इतिहास का पहला फाइनल है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":32,"local_id":"50032","quid":"Q1000073712","section":"GK","topic":"Ancient History: Miscellaneous","question":{"en":"In which part of a Hindu temple is the deity placed? [SSC CGL 10/10/26 Shift 2]","hi":"हिंदू मंदिर के किस भाग में देवता की प्रतिमा स्थापित की जाती है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Shikhara","hi":"शिखर"},"2":{"en":"Mandapa","hi":"मंडप"},"3":{"en":"Garbhagriha","hi":"गर्भगृह"},"4":{"en":"Gopuram","hi":"गोपुरम"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Garbhagriha</b><br>The deity is installed in the <b>garbhagriha</b> (literally \"womb chamber\"), the small, dark, innermost sanctum of the temple. It lies directly below the shikhara and only the priest normally enters it to perform worship.<br><br><br><b><u>Important Points:</u></b><br>• The <b>shikhara</b> is the tall curvilinear tower built over the garbhagriha in the Nagara (North Indian) style.<br>• The <b>mandapa</b> is the pillared hall where devotees assemble, while the <b>gopuram</b> is the monumental gateway tower of Dravidian (South Indian) temples.<br>• The Nagara style has no boundary wall or water tank as a rule and the Dravidian style has the gopuram, prakara (enclosure) and temple tank.<br>• The best examples of the Nagara style are the Khajuraho temples and the Sun Temple at Konark; the Dravidian style is seen at the Brihadeeswarar Temple, Thanjavur.","hi":"<b>सही उत्तर: विकल्प (3) – गर्भगृह</b><br>देवता की प्रतिमा मंदिर के सबसे भीतरी, छोटे और अंधकारपूर्ण पवित्र कक्ष <b>गर्भगृह</b> (शाब्दिक अर्थ \"गर्भ कक्ष\") में स्थापित की जाती है। यह शिखर के ठीक नीचे होता है और सामान्यतः केवल पुजारी ही पूजा हेतु इसमें प्रवेश करता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• शिखर नागर (उत्तर भारतीय) शैली में गर्भगृह के ऊपर बना ऊँचा वक्राकार शिखर होता है।<br>• मंडप स्तंभयुक्त सभा कक्ष है जहाँ भक्त एकत्र होते हैं, तथा गोपुरम द्रविड़ (दक्षिण भारतीय) मंदिरों का विशाल प्रवेश द्वार है।<br>• नागर शैली में सामान्यतः सीमा-दीवार या जलाशय नहीं होता, जबकि द्रविड़ शैली में गोपुरम, प्राकार (परिधि-दीवार) और मंदिर-तालाब होते हैं।<br>• नागर शैली के उत्कृष्ट उदाहरण खजुराहो के मंदिर तथा कोणार्क का सूर्य मंदिर हैं; द्रविड़ शैली तंजावुर के बृहदेश्वर मंदिर में दिखाई देती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":33,"local_id":"50033","quid":"Q1000073713","section":"GK","topic":"Static GK: Books and Authors","question":{"en":"Which Nobel Laureate wrote \"Blindness\", a powerful allegory about a mysterious epidemic and the collapse of civilization? [SSC CGL 10/10/26 Shift 2]","hi":"किस नोबेल विजेता ने \"ब्लाइंडनेस\" लिखी, जो एक रहस्यमय महामारी और सभ्यता के पतन पर आधारित एक शक्तिशाली रूपक है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Jose Saramago","hi":"जोज़े सारामागो"},"2":{"en":"Mario Vargas Llosa","hi":"मारियो वर्गास ल्योसा"},"3":{"en":"Gabriel Garcia Marquez","hi":"गेब्रियल गार्सिया मार्केज़"},"4":{"en":"Orhan Pamuk","hi":"ओरहान पामुक"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Jose Saramago</b><br>\"Blindness\" (Portuguese: <i>Ensaio sobre a Cegueira</i>, 1995) is a novel by the Portuguese writer <b>Jose Saramago</b>, in which an unexplained epidemic of white blindness destroys social order and exposes human nature.<br><br><br><b><u>Important Points:</u></b><br>• Jose Saramago won the <b>Nobel Prize in Literature in 1998</b>, the first Portuguese-language writer to do so; he also won the Camões Prize.<br>• His other famous works are <i>Baltasar and Blimunda</i>, <i>The Gospel According to Jesus Christ</i> and <i>The Year of the Death of Ricardo Reis</i>.<br>• <b>Gabriel Garcia Marquez</b> (Colombia) wrote <i>One Hundred Years of Solitude</i> and won the Nobel Prize in 1982.<br>• <b>Mario Vargas Llosa</b> (Peru) and <b>Orhan Pamuk</b> (Turkey) were Nobel laureates in 2010 and 2006 respectively; <i>Blindness</i> was adapted into the film <i>Blindness</i> (2008).","hi":"<b>सही उत्तर: विकल्प (1) – जोज़े सारामागो</b><br>\"ब्लाइंडनेस\" (पुर्तगाली: <i>Ensaio sobre a Cegueira</i>, 1995) पुर्तगाली लेखक <b>जोज़े सारामागो</b> का उपन्यास है, जिसमें श्वेत अंधता की एक अव्याख्यायित महामारी सामाजिक व्यवस्था को नष्ट कर मानव स्वभाव को उजागर करती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• जोज़े सारामागो को 1998 में साहित्य का नोबेल पुरस्कार मिला; वे यह सम्मान पाने वाले पहले पुर्तगाली भाषा के लेखक थे। उन्हें कामोएंस पुरस्कार भी मिला।<br>• उनकी अन्य प्रसिद्ध रचनाएँ <i>बाल्तासर एंड ब्लिमुंडा</i>, <i>द गॉस्पल अकॉर्डिंग टू जीसस क्राइस्ट</i> तथा <i>द ईयर ऑफ द डेथ ऑफ रिकार्डो रीस</i> हैं।<br>• गेब्रियल गार्सिया मार्केज़ (कोलंबिया) ने <i>वन हंड्रेड ईयर्स ऑफ सॉलिट्यूड</i> लिखी तथा 1982 में नोबेल पुरस्कार पाया।<br>• मारियो वर्गास ल्योसा (पेरू) तथा ओरहान पामुक (तुर्की) क्रमशः 2010 और 2006 के नोबेल विजेता रहे; <i>ब्लाइंडनेस</i> पर 2008 में इसी नाम की फिल्म बनी।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":34,"local_id":"50034","quid":"Q1000073714","section":"GK","topic":"Static GK: Awards and Honours","question":{"en":"Who was the first recipient of Jnanpith Award in India? [SSC CGL 10/10/26 Shift 2]","hi":"भारत में ज्ञानपीठ पुरस्कार के प्रथम प्राप्तकर्ता कौन थे? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"T.S. Bandyopadhyaya","hi":"टी.एस. बंद्योपाध्याय"},"2":{"en":"G.S. Kurup","hi":"जी.एस. कुरुप"},"3":{"en":"Uma Shankar Joshi","hi":"उमाशंकर जोशी"},"4":{"en":"K.V. Puttappa","hi":"के.वी. पुत्तप्पा"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – G.S. Kurup</b><br>The first Jnanpith Award (1965) was given to the Malayalam poet <b>G. Sankara Kurup</b> for his work <i>Odakkuzhal</i>. The award is India’s highest literary honour, given by the Bharatiya Jnanpith for creative writing in any of the languages listed in the Eighth Schedule.<br><br><br><b><u>Important Points:</u></b><br>• The Jnanpith Award was instituted in <b>1961</b> by the Bharatiya Jnanpith, founded by <b>Sahu Shanti Prasad Jain</b>, and was first awarded in 1965.<br>• It carries a cash prize, a bronze statue of Vagdevi (Saraswati) and a citation; it is given for a lifetime body of work, not for a single book.<br>• <b>G.S. Kurup</b> was a Malayalam poet from Kerala and a Padma Bhushan awardee.<br>• Hindi writer <b>Sumitranandan Pant</b> received it in 1968 and Kannada poet K.V. Puttappa (Kuvempu) in 1967; Uma Shankar Joshi won it in 1967 for Gujarati.","hi":"<b>सही उत्तर: विकल्प (2) – जी.एस. कुरुप</b><br>प्रथम ज्ञानपीठ पुरस्कार (1965) मलयालम कवि <b>जी. शंकर कुरुप</b> को उनकी रचना <i>ओडक्कुझल</i> के लिए दिया गया। यह भारत का सर्वोच्च साहित्यिक सम्मान है, जो भारतीय ज्ञानपीठ द्वारा आठवीं अनुसूची में सम्मिलित किसी भाषा में सृजनात्मक लेखन हेतु दिया जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ज्ञानपीठ पुरस्कार की स्थापना 1961 में साहू शांति प्रसाद जैन द्वारा स्थापित भारतीय ज्ञानपीठ ने की तथा पहली बार 1965 में प्रदान किया गया।<br>• इसमें नकद पुरस्कार, वाग्देवी (सरस्वती) की कांस्य प्रतिमा तथा प्रशस्ति-पत्र दिया जाता है; यह किसी एक पुस्तक के स्थान पर आजीवन साहित्यिक योगदान हेतु दिया जाता है।<br>• जी.एस. कुरुप केरल के मलयालम कवि तथा पद्म भूषण से सम्मानित थे।<br>• हिंदी लेखक सुमित्रानंदन पंत को यह 1968 में तथा कन्नड़ कवि के.वी. पुत्तप्पा (कुवेम्पु) को 1967 में मिला; उमाशंकर जोशी ने 1967 में गुजराती हेतु यह पुरस्कार जीता।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":35,"local_id":"50035","quid":"Q1000073715","section":"GK","topic":"Ancient History: Indus Valley Civilization","question":{"en":"Choose the correctly matched pairs related to archaeological features.<br><br>1.&nbsp;&nbsp;&nbsp;Lothal – Dockyard<br>2.&nbsp;&nbsp;&nbsp;Ropar – Horse burial<br>3.&nbsp;&nbsp;&nbsp;Mehrgarh – Early agriculture [SSC CGL 10/10/26 Shift 2]","hi":"पुरातात्विक विशेषताओं से संबंधित सही सुमेलित युग्म चुनिए।<br><br>1.&nbsp;&nbsp;&nbsp;लोथल – गोदी (डॉकयार्ड)<br>2.&nbsp;&nbsp;&nbsp;रोपड़ – अश्व दफन<br>3.&nbsp;&nbsp;&nbsp;मेहरगढ़ – आरंभिक कृषि [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"1 and 3 only","hi":"केवल 1 और 3"},"2":{"en":"2 and 3 only","hi":"केवल 2 और 3"},"3":{"en":"1 and 2 only","hi":"केवल 1 और 2"},"4":{"en":"1, 2, and 3","hi":"1, 2 और 3"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – 1 and 3 only</b><br>Lothal in Gujarat had a tidal <b>dockyard</b> and was a bead-making centre, while Mehrgarh in Baluchistan shows the <b>earliest evidence of agriculture</b> in the subcontinent. Ropar (Rupnagar, Punjab) is known for the earliest evidence of a dog buried with a human and for Harappan remains — <b>not</b> for horse burial, so pair 2 is wrong.<br><br><br><b><u>Important Points:</u></b><br>• Mehrgarh (c. 7000 BCE) is the earliest <b>Neolithic</b> site of the subcontinent, with evidence of wheat and barley cultivation and animal domestication.<br>• Lothal was also known for bead manufacturing and the Mesopotamian-style <b>Persian Gulf seal</b>; Surkotada in Gujarat has the doubtful bone remains claimed as horse.<br>• Ropar is famous for the discovery of a burial where a human was buried with a dog, and for a Harappan seal.<br>• Harappa gave remains of a cemetery (R-37) and Mohenjodaro the Great Bath and the bronze \"Dancing Girl\".","hi":"<b>सही उत्तर: विकल्प (1) – केवल 1 और 3</b><br>गुजरात के लोथल में ज्वारीय <b>गोदी (Dockyard)</b> तथा मनका निर्माण केंद्र था, जबकि बलूचिस्तान का मेहरगढ़ उपमहाद्वीप में <b>कृषि के प्राचीनतम प्रमाण</b> प्रस्तुत करता है। रोपड़ (रूपनगर, पंजाब) मानव के साथ कुत्ते के दफन तथा हड़प्पा अवशेषों हेतु जाना जाता है — <b>अश्व दफन</b> हेतु नहीं; अतः युग्म 2 गलत है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मेहरगढ़ (लगभग 7000 ईसा पूर्व) उपमहाद्वीप का प्राचीनतम नवपाषाण स्थल है, जहाँ गेहूँ-जौ की खेती तथा पशुपालन के प्रमाण मिले।<br>• लोथल मनका निर्माण तथा मेसोपोटामिया शैली की फारस की खाड़ी मुद्रा हेतु भी प्रसिद्ध था; गुजरात के सुरकोटडा से अश्व संबंधी विवादित अस्थि अवशेष मिले।<br>• रोपड़ मानव के साथ कुत्ते के दफन तथा हड़प्पा मुद्रा की खोज हेतु प्रसिद्ध है।<br>• हड़प्पा से कब्रिस्तान (R-37) तथा मोहनजोदड़ो से विशाल स्नानागार और कांस्य \"नृत्य करती लड़की\" प्राप्त हुई।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":36,"local_id":"50036","quid":"Q1000073716","section":"GK","topic":"Geography: Himalayas","question":{"en":"The Kumaun Himalaya lie between: [SSC CGL 10/10/26 Shift 2]","hi":"कुमाऊँ हिमालय किनके बीच स्थित है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"The Indus and Sutlej rivers","hi":"सिंधु और सतलुज नदियों"},"2":{"en":"The Kali and Teesta rivers","hi":"काली और तीस्ता नदियों"},"3":{"en":"The Sutlej and Kali rivers","hi":"सतलुज और काली नदियों"},"4":{"en":"The Ravi and Jhelum rivers","hi":"रावी और झेलम नदियों"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – The Sutlej and Kali rivers</b><br>The Kumaun Himalaya extend between the <b>Sutlej</b> river in the west and the <b>Kali</b> river in the east. The Kali river is also called the Sharda and forms the boundary between Nepal and India.<br><br><br><b><u>Important Points:</u></b><br>• Longitudinal divisions of the Himalaya: <b>Punjab/Kashmir Himalaya</b> (Indus–Sutlej), <b>Kumaun Himalaya</b> (Sutlej–Kali) and <b>Nepal Himalaya</b> (Kali–Teesta).<br>• The Kumaun Himalaya includes Nanda Devi (7,816 m), the highest peak wholly within India, and the hill stations of Nainital and Almora.<br>• West of the Indus is the <b>Trans-Himalaya</b> (Karakoram, Ladakh, Zanskar), and the Assam Himalaya lies east of the Teesta.<br>• The Kali river originates from the Kalapani glacier near Lipulekh and joins the Ghaghara, a tributary of the Ganga.","hi":"<b>सही उत्तर: विकल्प (3) – सतलुज और काली नदियों</b><br>कुमाऊँ हिमालय पश्चिम में <b>सतलुज</b> नदी तथा पूर्व में <b>काली</b> नदी के बीच विस्तृत है। काली नदी को शारदा भी कहा जाता है और यह नेपाल-भारत की सीमा बनाती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• हिमालय के अनुदैर्ध्य विभाग: पंजाब/कश्मीर हिमालय (सिंधु–सतलुज), कुमाऊँ हिमालय (सतलुज–काली) तथा नेपाल हिमालय (काली–तीस्ता)।<br>• कुमाऊँ हिमालय में नंदा देवी (7,816 मीटर), जो पूर्णतः भारत में स्थित सर्वोच्च शिखर है, तथा नैनीताल व अल्मोड़ा जैसे हिल स्टेशन हैं।<br>• सिंधु के पश्चिम में <b>ट्रांस-हिमालय</b> (काराकोरम, लद्दाख, ज़ांस्कर) है तथा तीस्ता के पूर्व में असम हिमालय आता है।<br>• काली नदी लिपुलेख के निकट कालापानी हिमनद से निकलती है और गंगा की सहायक घाघरा में मिलती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":37,"local_id":"50037","quid":"Q1000073717","section":"GK","topic":"Biology: Nutrients","question":{"en":"Which vital micronutrient is crucial for DNA replication and, when deficient, results in megaloblastic anaemia? [SSC CGL 10/10/26 Shift 2]","hi":"कौन-सा आवश्यक सूक्ष्म पोषक तत्व DNA प्रतिकृति के लिए निर्णायक है और इसकी कमी से मेगालोब्लास्टिक एनीमिया हो जाता है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Folate","hi":"फोलेट"},"2":{"en":"Vitamin B<sub>12</sub>","hi":"विटामिन B<sub>12</sub>"},"3":{"en":"Iron","hi":"आयरन"},"4":{"en":"Vitamin C","hi":"विटामिन C"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Vitamin B<sub>12</sub></b><br>Vitamin B<sub>12</sub> (cobalamin) is needed for the synthesis of DNA during red blood cell formation. Its deficiency causes <b>megaloblastic anaemia</b>, in which the RBC precursors in bone marrow remain large and immature, along with neurological symptoms.<br><br><br><b><u>Important Points:</u></b><br>• Vitamin B<sub>12</sub> is a <b>water-soluble</b> vitamin stored in the liver and is obtained from animal foods and dairy; its absorption needs <b>intrinsic factor</b> from the stomach.<br>• Its deficiency also causes <b>pernicious anaemia</b> and nerve damage; folate deficiency causes megaloblastic anaemia in pregnancy.<br>• <b>Iron</b> deficiency causes microcytic hypochromic anaemia, and vitamin C deficiency causes <b>scurvy</b>.<br>• Vitamin B<sub>12</sub> is called the anti-pernicious anaemia factor and contains the metal <b>cobalt</b>.","hi":"<b>सही उत्तर: विकल्प (2) – विटामिन B<sub>12</sub></b><br>विटामिन B<sub>12</sub> (कोबालामिन) लाल रक्त कोशिकाओं के निर्माण के दौरान DNA संश्लेषण हेतु आवश्यक है। इसकी कमी से <b>मेगालोब्लास्टिक एनीमिया</b> होता है, जिसमें अस्थि मज्जा में लाल रक्त कोशिकाओं के पूर्वगामी बड़े व अपरिपक्व रह जाते हैं और साथ ही स्नायविक लक्षण भी दिखते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• विटामिन B<sub>12</sub> जल में घुलनशील विटामिन है, यकृत में संचित रहता है, पशु-आहार व दुग्ध से प्राप्त होता है तथा इसके अवशोषण हेतु आमाशय के <b>अंतःकुंच (Intrinsic factor)</b> की आवश्यकता होती है।<br>• इसकी कमी से <b>घातक रक्ताल्पता (Pernicious anaemia)</b> तथा तंत्रिका क्षति भी होती है; फोलेट की कमी गर्भावस्था में मेगालोब्लास्टिक एनीमिया करती है।<br>• आयरन की कमी से माइक्रोसाइटिक हाइपोक्रोमिक एनीमिया तथा विटामिन C की कमी से <b>स्कर्वी</b> होता है।<br>• विटामिन B<sub>12</sub> को घातक रक्ताल्पता-रोधी कारक कहा जाता है और इसमें धातु <b>कोबाल्ट</b> होती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":38,"local_id":"50038","quid":"Q1000073718","section":"GK","topic":"Environment: Miscellaneous","question":{"en":"In the India State of Forest Report (ISFR) 2023, which Indian state reported the highest increase in mangrove cover by 253.06 km<sup>2</sup>? [SSC CGL 10/10/26 Shift 2]","hi":"भारत वन स्थिति रिपोर्ट (ISFR) 2023 में, किस भारतीय राज्य ने मैंग्रोव आवरण में 253.06 वर्ग किमी की सर्वाधिक वृद्धि दर्ज की? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Andhra Pradesh","hi":"आंध्र प्रदेश"},"2":{"en":"Odisha","hi":"ओडिशा"},"3":{"en":"West Bengal","hi":"पश्चिम बंगाल"},"4":{"en":"Gujarat","hi":"गुजरात"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Gujarat</b><br>As per ISFR 2023, Gujarat recorded the highest increase of <b>253.06 km<sup>2</sup></b> in mangrove cover between 2001 and 2023, through large-scale plantation, community participation and public-private partnership. In total mangrove cover, however, West Bengal is still first.<br><br><br><b><u>Important Points:</u></b><br>• India’s total mangrove cover is <b>4,991.68 km<sup>2</sup></b>, about 0.15% of the geographical area, as per ISFR 2023.<br>• State-wise mangrove cover: <b>West Bengal (42.45%) &gt; Gujarat (23.32%) &gt; Andaman &amp; Nicobar (12.19%)</b>; the Sundarbans is the largest mangrove forest in the world.<br>• ISFR is published <b>biennially</b> by the Forest Survey of India, Dehradun, and ISFR 2023 is the 18th edition.<br>• India’s forest and tree cover is about <b>25.17%</b> of the geographical area; Madhya Pradesh has the largest forest area and Mizoram the highest percentage of forest cover.","hi":"<b>सही उत्तर: विकल्प (4) – गुजरात</b><br>ISFR 2023 के अनुसार गुजरात ने 2001 से 2023 के बीच व्यापक वृक्षारोपण, सामुदायिक सहभागिता तथा सार्वजनिक-निजी भागीदारी के माध्यम से मैंग्रोव आवरण में <b>253.06 वर्ग किमी</b> की सर्वाधिक वृद्धि दर्ज की। कुल मैंग्रोव आवरण में पश्चिम बंगाल अब भी प्रथम है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ISFR 2023 के अनुसार भारत का कुल मैंग्रोव आवरण 4,991.68 वर्ग किमी है, जो भौगोलिक क्षेत्र का लगभग 0.15% है।<br>• राज्यवार मैंग्रोव आवरण: पश्चिम बंगाल (42.45%) &gt; गुजरात (23.32%) &gt; अंडमान एवं निकोबार (12.19%); सुंदरबन विश्व का सबसे बड़ा मैंग्रोव वन है।<br>• ISFR को देहरादून स्थित भारतीय वन सर्वेक्षण द्वारा <b>द्विवार्षिक</b> रूप से प्रकाशित किया जाता है; ISFR 2023 18वाँ संस्करण है।<br>• भारत का वन एवं वृक्ष आवरण भौगोलिक क्षेत्र का लगभग 25.17% है; सर्वाधिक वन क्षेत्र मध्य प्रदेश में तथा सर्वाधिक प्रतिशत वन आवरण मिजोरम में है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":39,"local_id":"50039","quid":"Q1000073719","section":"GK","topic":"Geography: Agriculture","question":{"en":"Which of the following crops is most suitable for dryland farming? [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सी फसल शुष्कभूमि (ड्राईलैंड) कृषि के लिए सर्वाधिक उपयुक्त है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Rice","hi":"चावल"},"2":{"en":"Wheat","hi":"गेहूँ"},"3":{"en":"Ragi","hi":"रागी"},"4":{"en":"Cotton","hi":"कपास"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Ragi</b><br>Ragi (finger millet) is a hardy millet that grows in areas of low and erratic rainfall, poor soils and high temperature, and is therefore a classic dryland crop. Rice and wheat need assured irrigation and cotton is grown in the black soil belt with moderate rainfall.<br><br><br><b><u>Important Points:</u></b><br>• Dryland farming is practised in areas with annual rainfall below 75 cm, mainly in Rajasthan, Gujarat, Madhya Pradesh, Maharashtra and the Deccan plateau.<br>• Millets — ragi, jowar, bajra, kodo, kutki, sanwa — are called <b>nutri-cereals</b>; 2023 was observed as the International Year of Millets.<br>• Ragi is rich in <b>calcium</b> and dietary fibre, and Karnataka is India’s largest ragi producer.<br>• Rice is a <b>kharif</b> crop needing 100–150 cm rainfall, wheat is the main <b>rabi</b> crop of the northern plains, and cotton is a kharif cash crop of the Deccan lava soil.","hi":"<b>सही उत्तर: विकल्प (3) – रागी</b><br>रागी (रागी/मडुआ) एक सहनशील मोटा अनाज है जो कम व अनियमित वर्षा, निर्धन मृदा तथा उच्च तापमान वाले क्षेत्रों में उगती है; अतः यह शुष्कभूमि कृषि की उत्कृष्ट फसल है। चावल व गेहूँ को सुनिश्चित सिंचाई चाहिए तथा कपास काली मृदा क्षेत्र में मध्यम वर्षा के साथ उगाई जाती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• शुष्कभूमि कृषि उन क्षेत्रों में की जाती है जहाँ वार्षिक वर्षा 75 सेमी से कम होती है, मुख्यतः राजस्थान, गुजरात, मध्य प्रदेश, महाराष्ट्र तथा दक्कन पठार में।<br>• मोटे अनाज — रागी, ज्वार, बाजरा, कोदो, कुटकी, सांवा — को <b>पोषक अनाज (Nutri-cereals)</b> कहा जाता है; 2023 को अंतर्राष्ट्रीय मोटा अनाज वर्ष घोषित किया गया था।<br>• रागी <b>कैल्शियम</b> तथा आहारीय फाइबर से भरपूर है तथा भारत में सर्वाधिक रागी कर्नाटक में उत्पादित होती है।<br>• चावल खरीफ की फसल है जिसे 100–150 सेमी वर्षा चाहिए, गेहूँ उत्तरी मैदानों की मुख्य रबी फसल है, तथा कपास दक्कन की लावा मृदा की खरीफ नकदी फसल है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":40,"local_id":"50040","quid":"Q1000073720","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"How many gold medals did India win at the 2022 Asian Games held in Hangzhou in 2023? [SSC CGL 10/10/26 Shift 2]","hi":"2023 में हांगझोऊ में आयोजित 2022 एशियाई खेलों में भारत ने कितने स्वर्ण पदक जीते? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"18"},"2":{"en":"22"},"3":{"en":"28"},"4":{"en":"38"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – 28</b><br>India won <b>28 gold</b> medals at the 19th Asian Games held at Hangzhou, China in 2023, its best-ever performance at the Games. The total tally was 107 medals — 28 gold, 38 silver and 41 bronze.<br><br><br><b><u>Important Points:</u></b><br>• The Hangzhou Asian Games were held from <b>23 September to 8 October 2023</b>; they were originally scheduled for 2022 but postponed due to COVID-19.<br>• India’s previous best was 16 gold at the 2018 Jakarta Asian Games; in Hangzhou, India finished <b>4th</b> in the medal table.<br>• China topped the table with 201 gold, followed by Japan and South Korea.<br>• The first Asian Games were held at <b>New Delhi in 1951</b>, and the next edition (20th) is scheduled at Aichi-Nagoya, Japan in 2026.","hi":"<b>सही उत्तर: विकल्प (3) – 28</b><br>2023 में चीन के हांगझोऊ में आयोजित 19वें एशियाई खेलों में भारत ने <b>28 स्वर्ण</b> पदक जीते, जो खेलों के इतिहास में उसका सर्वश्रेष्ठ प्रदर्शन था। कुल पदक 107 रहे — 28 स्वर्ण, 38 रजत तथा 41 कांस्य।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• हांगझोऊ एशियाई खेल 23 सितंबर से 8 अक्टूबर 2023 तक हुए; मूलतः ये 2022 में निर्धारित थे परंतु कोविड-19 के कारण स्थगित हुए।<br>• भारत का पूर्व सर्वश्रेष्ठ प्रदर्शन 2018 जकार्ता एशियाई खेलों में 16 स्वर्ण था; हांगझोऊ में भारत पदक तालिका में चौथे स्थान पर रहा।<br>• चीन 201 स्वर्ण के साथ प्रथम रहा, उसके बाद जापान और दक्षिण कोरिया रहे।<br>• प्रथम एशियाई खेल 1951 में नई दिल्ली में हुए थे तथा अगला (20वाँ) संस्करण 2026 में जापान के आइची-नागोया में निर्धारित है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":41,"local_id":"50041","quid":"Q1000073721","section":"GK","topic":"Ancient History: Vedic Age","question":{"en":"Which detail reflects women’s public participation in early Rig Vedic society? [SSC CGL 10/10/26 Shift 2]","hi":"कौन-सा विवरण प्रारंभिक ऋग्वैदिक समाज में महिलाओं की सार्वजनिक भागीदारी को दर्शाता है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"They held hereditary positions as tribal chiefs.","hi":"वे आनुवंशिक आधार पर जनजातीय प्रमुख के पद धारण करती थीं।"},"2":{"en":"They alone managed all religious property.","hi":"वे अकेले ही समस्त धार्मिक संपत्ति का प्रबंधन करती थीं।"},"3":{"en":"They actively attended the sabha and vidatha.","hi":"वे सभा और विदथ में सक्रिय रूप से भाग लेती थीं।"},"4":{"en":"They commanded separate military units.","hi":"वे पृथक सैन्य इकाइयों का नेतृत्व करती थीं।"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – They actively attended the sabha and vidatha.</b><br>Rig Vedic references show that women took part in the <b>sabha</b> (assembly of elders) and the <b>vidatha</b> (popular tribal assembly), which shows their public participation in early Vedic society. Women such as Gargi, Maitreyi and Ghosha composed hymns and participated in philosophical debates.<br><br><br><b><u>Important Points:</u></b><br>• Early Rig Vedic society was <b>patriarchal but not as rigid</b> as later times; women had freedom in marriage, education and religious ceremonies.<br>• The <b>sabha</b> and <b>samiti</b> were assemblies; the vidatha was an older tribal gathering for distribution and deliberation.<br>• Women seers were called <b>brahmavadinis</b> (e.g. Gargi and Maitreyi), while those who did not study were sadyodvahas.<br>• The position of women declined in the Later Vedic period with the rise of the Gotra system, child marriage and the loss of property rights.","hi":"<b>सही उत्तर: विकल्प (3) – वे सभा और विदथ में सक्रिय रूप से भाग लेती थीं।</b><br>ऋग्वैदिक संदर्भों से स्पष्ट होता है कि महिलाएँ <b>सभा</b> (वयोवृद्धों की सभा) तथा <b>विदथ</b> (जनजातीय जन-सभा) में भाग लेती थीं, जो प्रारंभिक वैदिक समाज में उनकी सार्वजनिक भागीदारी दर्शाता है। गार्गी, मैत्रेयी तथा घोषा जैसी महिलाओं ने मंत्रों की रचना की और दार्शनिक विमर्शों में भाग लिया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• प्रारंभिक ऋग्वैदिक समाज पितृसत्तात्मक था, परंतु बाद के समय की तरह कठोर नहीं; महिलाओं को विवाह, शिक्षा तथा धार्मिक अनुष्ठानों में स्वतंत्रता थी।<br>• सभा और समिति सभाएँ थीं; विदथ वितरण एवं विचार-विमर्श हेतु पुरानी जनजातीय सभा थी।<br>• विद्वान महिलाओं को <b>ब्रह्मवादिनी</b> कहा जाता था (जैसे गार्गी, मैत्रेयी), जबकि जो अध्ययन नहीं करती थीं उन्हें सद्योद्वाहा कहा जाता था।<br>• उत्तर वैदिक काल में गोत्र व्यवस्था, बाल-विवाह तथा संपत्ति अधिकारों के हनन के साथ महिलाओं की स्थिति में गिरावट आई।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":42,"local_id":"50042","quid":"Q1000073722","section":"GK","topic":"Current Affairs: Appointments and Resignations","question":{"en":"Which economist, who previously served as Director of the Institute of Economic Growth, is a full-time member of the 16<sup>th</sup> Finance Commission of India? [SSC CGL 10/10/26 Shift 2]","hi":"कौन-से अर्थशास्त्री, जो पूर्व में आर्थिक विकास संस्थान (Institute of Economic Growth) के निदेशक रह चुके हैं, भारत के 16<sup>वें</sup> वित्त आयोग के पूर्णकालिक सदस्य हैं? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Ajay Narayan Jha","hi":"अजय नारायण झा"},"2":{"en":"Manoj Panda","hi":"मनोज पांडा"},"3":{"en":"Soumya Kanti Ghosh","hi":"सौम्य कांति घोष"},"4":{"en":"Annie George Mathew","hi":"एनी जॉर्ज मैथ्यू"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Manoj Panda</b><br>Economist <b>Manoj Panda</b>, former Director of the Institute of Economic Growth, Delhi, was appointed a <b>full-time member</b> of the 16th Finance Commission in April 2024. The Commission is chaired by Arvind Panagariya.<br><br><br><b><u>Important Points:</u></b><br>• The Finance Commission is a <b>constitutional body</b> constituted by the President every <b>five years</b> under <b>Article 280</b>; it recommends the distribution of taxes between the Centre and states.<br>• The 16th Finance Commission (2026–31) is chaired by <b>Arvind Panagariya</b>; its other full-time members are Ajay Narayan Jha, Annie George Mathew and Manoj Panda.<br>• <b>Soumya Kanti Ghosh</b> is a part-time member, and the Commission’s report covers the period from 1 April 2026.<br>• The 15th Finance Commission was chaired by <b>N.K. Singh</b>, and the first Finance Commission (1951) was chaired by K.C. Neogy.","hi":"<b>सही उत्तर: विकल्प (2) – मनोज पांडा</b><br>दिल्ली स्थित आर्थिक विकास संस्थान के पूर्व निदेशक, अर्थशास्त्री <b>मनोज पांडा</b> अप्रैल 2024 में 16वें वित्त आयोग के <b>पूर्णकालिक सदस्य</b> नियुक्त किए गए। आयोग के अध्यक्ष अरविंद पनगढ़िया हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• वित्त आयोग एक <b>संवैधानिक निकाय</b> है, जिसे अनुच्छेद 280 के अंतर्गत राष्ट्रपति प्रत्येक पाँच वर्ष में गठित करते हैं; यह केंद्र-राज्यों के बीच करों के वितरण की सिफारिश करता है।<br>• 16वाँ वित्त आयोग (2026–31) अरविंद पनगढ़िया की अध्यक्षता में है; इसके अन्य पूर्णकालिक सदस्य अजय नारायण झा, एनी जॉर्ज मैथ्यू तथा मनोज पांडा हैं।<br>• सौम्य कांति घोष अंशकालिक सदस्य हैं तथा आयोग की रिपोर्ट 1 अप्रैल 2026 से की अवधि हेतु है।<br>• 15वें वित्त आयोग के अध्यक्ष एन.के. सिंह थे तथा प्रथम वित्त आयोग (1951) के अध्यक्ष के.सी. नियोगी थे।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":43,"local_id":"50043","quid":"Q1000073723","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"A Judicial Magistrate who was exercising jurisdiction throughout District A is transferred to an equivalent post in another area within the same State. No fresh order conferring judicial powers is issued after the transfer. Can the Magistrate continue to exercise the same judicial powers under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India? [SSC CGL 10/10/26 Shift 2]","hi":"एक न्यायिक मजिस्ट्रेट, जो पूरे जिला A में अधिकारक्षेत्र का प्रयोग कर रहा था, उसी राज्य के किसी अन्य क्षेत्र में समान पद पर स्थानांतरित कर दिया जाता है। स्थानांतरण के बाद न्यायिक शक्तियाँ प्रदान करने वाला कोई नया आदेश जारी नहीं होता। क्या मजिस्ट्रेट भारतीय नागरिक सुरक्षा संहिता, 2023 के अंतर्गत वही न्यायिक शक्तियाँ जारी रख सकता है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"No, because fresh conferment is mandatory after every transfer.","hi":"नहीं, क्योंकि प्रत्येक स्थानांतरण के बाद नई शक्तियाँ प्रदान करना अनिवार्य है।"},"2":{"en":"Yes, unless the high court or state government directs otherwise.","hi":"हाँ, जब तक उच्च न्यायालय या राज्य सरकार अन्यथा निर्देश न दे।"},"3":{"en":"Yes, but only for administrative powers, not judicial powers.","hi":"हाँ, परंतु केवल प्रशासनिक शक्तियों हेतु, न्यायिक शक्तियों हेतु नहीं।"},"4":{"en":"No, because powers lapse automatically upon transfer.","hi":"नहीं, क्योंकि स्थानांतरण पर शक्तियाँ स्वतः समाप्त हो जाती हैं।"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Yes, unless the high court or state government directs otherwise.</b><br>Under the BNSS, 2023, a Magistrate’s powers are attached to the office and continue to be exercisable after transfer to an equivalent post in another area of the same State, unless the High Court or the State Government directs otherwise. Fresh conferment is therefore not needed for every transfer.<br><br><br><b><u>Important Points:</u></b><br>• This follows <b>Section 12 of the old CrPC, 1973</b>, which is carried forward into the BNSS, 2023.<br>• Judicial Magistrates are appointed by the <b>High Court</b>, while Executive Magistrates are appointed by the State Government; the two are kept separate by the new Sanhita.<br>• The BNSS, 2023 has <b>531 sections</b>, 20 chapters and 2 schedules, and came into force on <b>1 July 2024</b>.<br>• The BNSS replaces the CrPC, 1973 and introduces provisions such as <b>zero FIR</b>, e-FIR, audio-video recording of searches and a time limit of 90 days for investigation in certain offences.","hi":"<b>सही उत्तर: विकल्प (2) – हाँ, जब तक उच्च न्यायालय या राज्य सरकार अन्यथा निर्देश न दे।</b><br>BNSS, 2023 के अंतर्गत मजिस्ट्रेट की शक्तियाँ पद से संबद्ध हैं और उसी राज्य के किसी अन्य क्षेत्र में समान पद पर स्थानांतरण के बाद भी जारी रहती हैं, जब तक उच्च न्यायालय या राज्य सरकार अन्यथा निर्देश न दें। अतः प्रत्येक स्थानांतरण पर नई शक्तियाँ प्रदान करना आवश्यक नहीं है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह पुरानी CrPC, 1973 की धारा 12 का अनुसरण है, जिसे BNSS, 2023 में आगे बढ़ाया गया है।<br>• न्यायिक मजिस्ट्रेट की नियुक्ति <b>उच्च न्यायालय</b> करता है, जबकि कार्यपालक मजिस्ट्रेट की नियुक्ति राज्य सरकार करती है; नई संहिता ने दोनों को पृथक रखा है।<br>• BNSS, 2023 में 531 धाराएँ, 20 अध्याय तथा 2 अनुसूचियाँ हैं और यह 1 जुलाई 2024 से प्रभावी हुई।<br>• BNSS ने CrPC, 1973 का स्थान लिया और <b>शून्य प्रथम सूचना रिपोर्ट (Zero FIR)</b>, ई-एफआईआर, तलाशी का ऑडियो-वीडियो रिकॉर्डिंग तथा कुछ अपराधों में जाँच हेतु 90 दिन की समय-सीमा जैसे प्रावधान जोड़े।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":44,"local_id":"50044","quid":"Q1000073724","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"Under the provisions of the Bharatiya Sakshya Adhiniyam 2023 in India, A is accused of committing a crime in Bengaluru. The defence proves that A was in Delhi at the exact time of commission of the crime. This fact is: [SSC CGL 10/10/26 Shift 2]","hi":"भारत में भारतीय साक्ष्य अधिनियम 2023 के प्रावधानों के अंतर्गत, A पर बेंगलुरु में अपराध करने का आरोप है। प्रतिवाद यह सिद्ध करता है कि अपराध होने के ठीक समय A दिल्ली में था। यह तथ्य है: [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Relevant as a fact forming part of the same transaction","hi":"सुसंगत है, क्योंकि यह उसी संव्यवहार का भाग बनने वाला तथ्य है"},"2":{"en":"Relevant as an exception under Section 10","hi":"सुसंगत है, क्योंकि यह धारा 10 के अंतर्गत अपवाद है"},"3":{"en":"Relevant because it is inconsistent with the fact in issue.","hi":"सुसंगत है, क्योंकि यह विवाद्यक तथ्य के साथ असंगत है।"},"4":{"en":"Irrelevant unless corroborated by confession","hi":"असंगत है, जब तक स्वीकारोक्ति से इसका समर्थन न हो"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Relevant because it is inconsistent with the fact in issue.</b><br>The fact that A was in Delhi at the time of the crime is a plea of <b>alibi</b>. Under the BSA, 2023 a fact is relevant if it is inconsistent with any fact in issue or relevant fact, so the alibi directly rebuts the prosecution’s claim that A committed the crime in Bengaluru.<br><br><br><b><u>Important Points:</u></b><br>• The section on facts inconsistent with facts in issue corresponds to <b>Section 11 of the Indian Evidence Act, 1872</b>, now in the Bharatiya Sakshya Adhiniyam, 2023.<br>• <b>Alibi</b> is not a confession; it is a positive defence that the accused was elsewhere, and the burden to prove it lies on the accused.<br>• \"Fact in issue\" means a fact in dispute on which the decision depends; \"relevant fact\" is any fact connected with it so as to make it probable or improbable.<br>• The BSA, 2023 has <b>170 sections</b> and replaced the Indian Evidence Act, 1872 with effect from 1 July 2024.","hi":"<b>सही उत्तर: विकल्प (3) – सुसंगत है, क्योंकि यह विवाद्यक तथ्य के साथ असंगत है।</b><br>यह तथ्य कि घटना के समय A दिल्ली में था, <b>अन्यत्र-उपस्थिति (Alibi)</b> का अभिवादन है। BSA, 2023 के अनुसार कोई तथ्य सुसंगत है यदि वह विवाद्यक तथ्य या सुसंगत तथ्य के असंगत हो, अतः अलिबी अभियोजन के इस दावे का सीधा खंडन करता है कि A ने बेंगलुरु में अपराध किया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• विवाद्यक तथ्यों के असंगत तथ्य वाला प्रावधान भारतीय साक्ष्य अधिनियम, 1872 की धारा 11 के समान है, जो अब भारतीय साक्ष्य अधिनियम, 2023 में है।<br>• <b>अलिबी</b> स्वीकारोक्ति नहीं है; यह एक सकारात्मक प्रतिवाद है कि अभियुक्त अन्यत्र था, तथा इसे सिद्ध करने का भार अभियुक्त पर है।<br>• \"विवाद्यक तथ्य\" का अर्थ है विवादित तथ्य जिस पर निर्णय निर्भर करता है; \"सुसंगत तथ्य\" वह तथ्य है जो उससे इस प्रकार जुड़ा हो कि उसे संभाव्य या असंभाव्य बनाए।<br>• BSA, 2023 में 170 धाराएँ हैं और इसने 1 जुलाई 2024 से भारतीय साक्ष्य अधिनियम, 1872 का स्थान लिया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":45,"local_id":"50045","quid":"Q1000073725","section":"GK","topic":"Ancient History: Gupta Dynasty","question":{"en":"Consider the following statements regarding Indian temple architecture:<br>1. Panchayatana temples feature one main central shrine surrounded by four subsidiary shrines.<br>2.The Dashavatara Temple at Deogarh is an example of the Panchayatana style of architecture.<br>Which of the statements given above is/are <b>correct</b>? [SSC CGL 10/10/26 Shift 2]","hi":"भारतीय मंदिर स्थापत्य के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br>1. पंचायतन मंदिरों में एक मुख्य केंद्रीय मंदिर होता है जो चार सहायक मंदिरों से घिरा रहता है।<br>2. देवगढ़ का दशावतार मंदिर पंचायतन शैली के स्थापत्य का उदाहरण है।<br>उपर्युक्त कथनों में से कौन-सा/से <b>सही</b> है/हैं? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"1 only","hi":"केवल 1"},"2":{"en":"2 only","hi":"केवल 2"},"3":{"en":"Both 1 and 2","hi":"1 और 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न 1, न ही 2"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both 1 and 2</b><br>A Panchayatana temple has a main shrine in the centre with four smaller shrines at the four corners, and the <b>Dashavatara Temple at Deogarh</b> (Lalitpur, Uttar Pradesh) of the Gupta period is a classic example of this style. Both statements are therefore correct.<br><br><br><b><u>Important Points:</u></b><br>• The Dashavatara Temple at Deogarh (c. 6th century CE) is one of the earliest Gupta temples with a <b>shikhara</b> and panels showing Vishnu’s avatars, Ganga-Yamuna and Seshasayi Vishnu.<br>• Gupta temples mark the beginning of <b>Nagara</b> architecture; examples are the Deogarh temple, Bhitargaon brick temple and the Mahabodhi Temple, Bodh Gaya.<br>• The three broad temple styles are <b>Nagara</b> (north), <b>Dravida</b> (south) and <b>Vesara</b> (Deccan, between the Vindhyas and the Krishna river).<br>• Panchayatana temples became very popular under the <b>Chandela</b> rulers, as seen at Khajuraho (Kandariya Mahadeva temple).","hi":"<b>सही उत्तर: विकल्प (3) – 1 और 2 दोनों</b><br>पंचायतन मंदिर में केंद्र में एक मुख्य मंदिर तथा चारों कोनों पर चार छोटे मंदिर होते हैं; गुप्तकालीन <b>देवगढ़ का दशावतार मंदिर</b> (ललितपुर, उत्तर प्रदेश) इस शैली का उत्कृष्ट उदाहरण है। अतः दोनों कथन सही हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• देवगढ़ का दशावतार मंदिर (लगभग 6वीं शताब्दी ई.) शिखर तथा विष्णु के अवतारों, गंगा-यमुना एवं शेषशायी विष्णु के फलकों वाले प्राचीनतम गुप्त मंदिरों में से है।<br>• गुप्त मंदिर <b>नागर</b> स्थापत्य के आरंभ का प्रतीक हैं; उदाहरण — देवगढ़ मंदिर, भीतरगाँव का ईंट मंदिर तथा बोधगया का महाबोधि मंदिर।<br>• मंदिर स्थापत्य की तीन प्रमुख शैलियाँ नागर (उत्तर), द्रविड़ (दक्षिण) तथा <b>वेसर</b> (दक्कन, विंध्य व कृष्णा नदी के बीच) हैं।<br>• पंचायतन मंदिर <b>चंदेल</b> शासकों के समय अत्यंत लोकप्रिय हुए, जैसा खजुराहो (कंदरिया महादेव मंदिर) में दिखता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":46,"local_id":"50046","quid":"Q1000073726","section":"GK","topic":"Current Affairs: National News","question":{"en":"In February 2026, how many cheetahs arrived from Botswana to be reintroduced at Kuno National Park? [SSC CGL 10/10/26 Shift 2]","hi":"फरवरी 2026 में, कुनो राष्ट्रीय उद्यान में पुनःस्थापन हेतु बोत्सवाना से कितने चीते पहुँचे? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"6"},"2":{"en":"9"},"3":{"en":"7"},"4":{"en":"3"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – 9</b><br>In February 2026, <b>nine cheetahs</b> (six females and three males) gifted by <b>Botswana</b> were released at Kuno National Park, Madhya Pradesh, taking India’s total cheetah population to 48. Botswana became the third African country, after Namibia and South Africa, to send cheetahs to India.<br><br><br><b><u>Important Points:</u></b><br>• Project Cheetah began on <b>17 September 2022</b>, when eight cheetahs from <b>Namibia</b> were released at Kuno by the Prime Minister.<br>• The cheetahs from Botswana were brought by IAF’s C-17 Globemaster to Gwalior and then airlifted by helicopters to Kuno, where they were kept in quarantine enclosures.<br>• Kuno National Park is in <b>Sheopur district, Madhya Pradesh</b>, on the banks of the Kuno river, and was chosen for its grassland-savanna habitat and prey base.<br>• The cheetah was declared extinct in India in <b>1952</b>; the last recorded cheetah was shot by Maharaja Ramanuj Pratap Singh Deo of Koriya in 1947.","hi":"<b>सही उत्तर: विकल्प (2) – 9</b><br>फरवरी 2026 में बोत्सवाना द्वारा उपहार में दिए गए <b>नौ चीते</b> (छह मादा और तीन नर) मध्य प्रदेश के कुनो राष्ट्रीय उद्यान में छोड़े गए, जिससे भारत की कुल चीता आबादी 48 हो गई। बोत्सवाना, नामीबिया और दक्षिण अफ्रीका के बाद चीते भेजने वाला तीसरा अफ्रीकी देश बना।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• चीता परियोजना (Project Cheetah) 17 सितंबर 2022 को आरंभ हुई, जब प्रधानमंत्री ने नामीबिया से लाए आठ चीतों को कुनो में छोड़ा।<br>• बोत्सवाना से चीतों को IAF के C-17 ग्लोबमास्टर से ग्वालियर लाया गया और फिर हेलीकॉप्टर से कुनो भेजा गया, जहाँ उन्हें संगरोध (quarantine) बाड़ों में रखा गया।<br>• कुनो राष्ट्रीय उद्यान मध्य प्रदेश के <b>श्योपुर जिले</b> में कुनो नदी के तट पर है; घास-मैदान (सवाना) आवास तथा शिकार की उपलब्धता के कारण इसे चुना गया।<br>• भारत में चीता <b>1952</b> में विलुप्त घोषित किया गया; अंतिम दर्ज चीता 1947 में कोरिया के महाराजा रामानुज प्रताप सिंह देव ने मारा था।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":47,"local_id":"50047","quid":"Q1000073727","section":"GK","topic":"Polity: Local Government","question":{"en":"According to the Urban and Regional Development Plans Formulation and Implementation (URDPFI) Guidelines, which constitutional amendment granted constitutional status to Urban Local Bodies in India? [SSC CGL 10/10/26 Shift 2]","hi":"शहरी एवं क्षेत्रीय विकास योजना निर्माण एवं क्रियान्वयन (URDPFI) दिशानिर्देशों के अनुसार, किस संविधान संशोधन ने भारत में शहरी स्थानीय निकायों को संवैधानिक दर्जा प्रदान किया? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"42<sup>nd</sup> Constitutional Amendment","hi":"42<sup>वाँ</sup> संविधान संशोधन"},"2":{"en":"44<sup>th</sup> Constitutional Amendment","hi":"44<sup>वाँ</sup> संविधान संशोधन"},"3":{"en":"52<sup>nd</sup> Constitutional Amendment","hi":"52<sup>वाँ</sup> संविधान संशोधन"},"4":{"en":"74<sup>th</sup> Constitutional Amendment","hi":"74<sup>वाँ</sup> संविधान संशोधन"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – 74<sup>th</sup> Constitutional Amendment</b><br>The <b>74th Constitutional Amendment Act, 1992</b> gave constitutional status to Urban Local Bodies by inserting <b>Part IX-A</b> (Articles 243-P to 243-ZG) and the <b>Twelfth Schedule</b> (18 subjects) in the Constitution, and it came into force on 1 June 1993.<br><br><br><b><u>Important Points:</u></b><br>• Urban local bodies provided for are Nagar Panchayat (transitional area), Municipal Council (smaller urban area) and Municipal Corporation (larger urban area).<br>• The <b>73rd Amendment Act, 1992</b> dealt with Panchayati Raj (Part IX, Eleventh Schedule with 29 subjects); it came into force on 24 April 1993.<br>• Both amendments added provisions for a <b>State Election Commission</b> and <b>State Finance Commission</b>, and fixed a five-year term for the bodies.<br>• The <b>42nd Amendment (1976)</b> added \"urban local bodies\" to the State List as part of local self-government; the 44th Amendment (1978) reversed several changes of the 42nd and the 52nd (1985) added the anti-defection Tenth Schedule.</br>","hi":"<b>सही उत्तर: विकल्प (4) – 74<sup>वाँ</sup> संविधान संशोधन</b><br>74वें संविधान संशोधन अधिनियम, 1992 ने संविधान में <b>भाग IX-A</b> (अनुच्छेद 243-P से 243-ZG) तथा <b>बारहवीं अनुसूची</b> (18 विषय) जोड़कर शहरी स्थानीय निकायों को संवैधानिक दर्जा दिया; यह 1 जून 1993 से प्रभावी हुआ।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• प्रावधानित शहरी स्थानीय निकाय हैं — नगर पंचायत (संक्रमणकालीन क्षेत्र), नगर परिषद (छोटा शहरी क्षेत्र) तथा नगर निगम (बड़ा शहरी क्षेत्र)।<br>• 73वें संविधान संशोधन अधिनियम, 1992 ने पंचायती राज (भाग IX, ग्यारहवीं अनुसूची के 29 विषय) से संबंधित प्रावधान किए; यह 24 अप्रैल 1993 से प्रभावी हुआ।<br>• दोनों संशोधनों ने <b>राज्य निर्वाचन आयोग</b> तथा <b>राज्य वित्त आयोग</b> के प्रावधान जोड़े और निकायों का कार्यकाल पाँच वर्ष निर्धारित किया।<br>• 42वें संशोधन (1976) ने स्थानीय स्वशासन के अंतर्गत \"शहरी स्थानीय निकाय\" को राज्य सूची में जोड़ा; 44वें संशोधन (1978) ने 42वें के अनेक प्रावधान बदले तथा 52वें (1985) ने दल-बदल विरोधी दसवीं अनुसूची जोड़ी।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":48,"local_id":"50048","quid":"Q1000073728","section":"GK","topic":"Economics: Basics of Economy","question":{"en":"Which of the following best explains how Foreign Direct Investment (FDI) differs from Foreign Institutional Investment (FII)? [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सा यह सर्वोत्तम रूप से स्पष्ट करता है कि प्रत्यक्ष विदेशी निवेश (FDI) संस्थागत विदेशी निवेश (FII) से किस प्रकार भिन्न है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Foreign Direct Investment (FDI) cannot be made in developing economies and is limited to developed countries","hi":"प्रत्यक्ष विदेशी निवेश (FDI) विकासशील अर्थव्यवस्थाओं में नहीं किया जा सकता और यह केवल विकसित देशों तक सीमित है"},"2":{"en":"Foreign Direct Investment (FDI) consists only of funds invested by foreign governments and excludes private investors","hi":"प्रत्यक्ष विदेशी निवेश (FDI) में केवल विदेशी सरकारों द्वारा निवेशित धन आता है और निजी निवेशक बाहर रहते हैं"},"3":{"en":"Foreign Direct Investment (FDI) mainly involves short-term investment and trading in financial securities","hi":"प्रत्यक्ष विदेशी निवेश (FDI) मुख्यतः अल्पकालिक निवेश और वित्तीय प्रतिभूतियों में व्यापार से संबंधित है"},"4":{"en":"Foreign Direct Investment (FDI) creates a lasting interest and significant managerial influence in an enterprise","hi":"प्रत्यक्ष विदेशी निवेश (FDI) किसी उद्यम में स्थायी हित तथा महत्वपूर्ण प्रबंधकीय प्रभाव उत्पन्न करता है"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Foreign Direct Investment (FDI) creates a lasting interest and significant managerial influence in an enterprise</b><br>FDI means a long-term investment that gives the investor a lasting interest and a significant degree of influence in the management of the enterprise, usually an equity stake of 10% or more. FII, on the other hand, is short-term investment in shares, bonds and other securities through the stock market without management control.<br><br><br><b><u>Important Points:</u></b><br>• FDI inflows are recorded in the <b>capital account</b> and bring technology, managerial skills and stable long-term capital.<br>• FII is also called <b>hot money</b> as it can leave quickly and causes volatility in the stock market.<br>• FDI is allowed in India through the <b>automatic route</b> and the <b>government (approval) route</b>; the sectors and caps are set out in the Consolidated FDI Policy of DPIIT.<br>• Singapore and Mauritius are among the largest sources of FDI into India, and the services sector receives the highest FDI inflows.","hi":"<b>सही उत्तर: विकल्प (4) – प्रत्यक्ष विदेशी निवेश (FDI) किसी उद्यम में स्थायी हित तथा महत्वपूर्ण प्रबंधकीय प्रभाव उत्पन्न करता है</b><br>FDI का अर्थ दीर्घकालिक निवेश है जो निवेशक को उद्यम के प्रबंधन में स्थायी हित तथा महत्वपूर्ण प्रभाव प्रदान करता है, सामान्यतः 10% या अधिक इक्विटी हिस्सा। इसके विपरीत FII शेयर बाजार के माध्यम से शेयर, बॉन्ड आदि प्रतिभूतियों में अल्पकालिक निवेश है, जिसमें प्रबंधन पर नियंत्रण नहीं होता।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• FDI को <b>पूँजी खाते</b> में दर्ज किया जाता है और यह तकनीक, प्रबंधकीय कौशल तथा स्थायी दीर्घकालिक पूँजी लाता है।<br>• FII को <b>तप्त धन (Hot money)</b> भी कहा जाता है, क्योंकि यह शीघ्र निकल सकता है और शेयर बाजार में अस्थिरता उत्पन्न करता है।<br>• भारत में FDI <b>स्वचालित मार्ग</b> तथा <b>सरकारी (अनुमोदन) मार्ग</b> से अनुमत है; क्षेत्र व सीमाएँ DPIIT की समेकित FDI नीति में दी गई हैं।<br>• भारत में FDI के प्रमुख स्रोतों में सिंगापुर व मॉरीशस सम्मिलित हैं तथा सर्वाधिक FDI सेवा क्षेत्र में आता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":49,"local_id":"50049","quid":"Q1000073729","section":"GK","topic":"Medieval History: Delhi Sultanate","question":{"en":"Which of the following correctly describes the primary historical distinction between the Iqta and Jagir systems in medieval India? [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सा मध्यकालीन भारत में इक़्ता और जागीर व्यवस्थाओं के बीच के प्रमुख ऐतिहासिक अंतर का सही वर्णन करता है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Iqtas were hereditary while Jagirs were temporary.","hi":"इक़्ते आनुवंशिक थे जबकि जागीरें अस्थायी थीं।"},"2":{"en":"Jagirs were exclusively religious grants whereas Iqtas were military grants.","hi":"जागीरें केवल धार्मिक अनुदान थीं जबकि इक़्ते सैन्य अनुदान थे।"},"3":{"en":"Iqta belonged to the Delhi Sultanate, while Jagir was prominent under the Mughals.","hi":"इक़्ता दिल्ली सल्तनत से संबंधित था, जबकि जागीर मुगलकाल में प्रमुख थी।"},"4":{"en":"Both terms referred to identical institutions throughout medieval India.","hi":"मध्यकालीन भारत में दोनों शब्द समान संस्थाओं को संदर्भित करते थे।"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Iqta belonged to the Delhi Sultanate, while Jagir was prominent under the Mughals.</b><br>The <b>iqta</b> system was the central revenue arrangement of the Delhi Sultanate, in which officers (muqtis or walis) collected revenue from a territory and kept a part for themselves. The <b>jagir</b> system became the main feature of the Mughal Empire, where mansabdars received the revenue of assigned lands in lieu of cash salary.<br><br><br><b><u>Important Points:</u></b><br>• The iqta system was introduced in India by <b>Iltutmish</b>, and the iqtadar was transferable, not hereditary.<br>• <b>Jagir</b> was the assignment of revenue from a parcel of land, while <b>altamgha</b> and <b>watan jagir</b> were special forms; <b>madad-i-maash</b> and <b>inam</b> were religious grants.<br>• The <b>mansabdari</b> system of Akbar fixed rank (zat and sawar) and jagirs were normally transferred after a few years.<br>• Alauddin Khalji and later Sher Shah Suri curtailed the privileges of iqtadars and increased state control over land revenue.","hi":"<b>सही उत्तर: विकल्प (3) – इक़्ता दिल्ली सल्तनत से संबंधित था, जबकि जागीर मुगलकाल में प्रमुख थी।</b><br><b>इक़्ता</b> व्यवस्था दिल्ली सल्तनत की केंद्रीय राजस्व व्यवस्था थी, जिसमें अधिकारी (मुक़्ती या वाली) किसी क्षेत्र से राजस्व वसूल कर उसका एक भाग अपने पास रखते थे। <b>जागीर</b> व्यवस्था मुगल साम्राज्य की मुख्य विशेषता बनी, जिसमें मनसबदारों को नकद वेतन के बदले आवंटित भूमि का राजस्व मिलता था।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• भारत में इक़्ता व्यवस्था <b>इल्तुतमिश</b> ने शुरू की; इक़्तेदार का स्थानांतरण होता था, पद आनुवंशिक नहीं था।<br>• जागीर भूमि के राजस्व का आवंटन थी, जबकि अलतमगा तथा वतन जागीर विशेष रूप थे; <b>मदद-ए-मआश</b> व <b>इनाम</b> धार्मिक अनुदान थे।<br>• अकबर की <b>मनसबदारी</b> व्यवस्था ने जात व सवार रैंक निर्धारित किए तथा जागीरें सामान्यतः कुछ वर्षों बाद स्थानांतरित की जाती थीं।<br>• अलाउद्दीन खिलजी तथा बाद में शेरशाह सूरी ने इक़्तेदारों के विशेषाधिकारों में कमी की और भू-राजस्व पर राज्य नियंत्रण बढ़ाया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":50,"local_id":"50050","quid":"Q1000073730","section":"GK","topic":"Economics: Five Year Plan and Industrial Policy Resolution","question":{"en":"Which of the following was a specific, monitorable social target set out in India’s Eleventh Five-Year Plan (2007–2012)? [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सा भारत की ग्यारहवीं पंचवर्षीय योजना (2007–2012) में निर्धारित एक विशिष्ट, निगरानी योग्य सामाजिक लक्ष्य था? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Reducing child malnutrition","hi":"बाल कुपोषण को कम करना"},"2":{"en":"Expanding defence production","hi":"रक्षा उत्पादन का विस्तार"},"3":{"en":"Increasing customs revenue","hi":"सीमा शुल्क राजस्व में वृद्धि"},"4":{"en":"Privatising public enterprises","hi":"सार्वजनिक उद्यमों का निजीकरण"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Reducing child malnutrition</b><br>The Eleventh Plan set a clear social target to reduce malnutrition among children in the <b>0–3 years</b> age group by half. Its 27 monitorable targets also covered poverty, education, health and environment indicators.<br><br><br><b><u>Important Points:</u></b><br>• The Eleventh Plan’s theme was <b>\"Faster and More Inclusive Growth\"</b> and its GDP growth target was 9%.<br>• Other targets: poverty ratio to fall by 10 percentage points, dropout rate in elementary education to come down to 20%, IMR to 28 per 1000, MMR to 1 per 1000 and sex ratio to be raised to 935 by 2011–12.<br>• It also aimed to increase forest and tree cover by 5 percentage points and provide clean drinking water to all by 2009.<br>• The Twelfth Plan (2012–17) was the last Five-Year Plan; the Planning Commission was replaced by NITI Aayog in 2015.","hi":"<b>सही उत्तर: विकल्प (1) – बाल कुपोषण को कम करना</b><br>ग्यारहवीं योजना ने 0–3 वर्ष आयु वर्ग के बच्चों में कुपोषण को आधा करने का स्पष्ट सामाजिक लक्ष्य निर्धारित किया। इसके 27 निगरानी योग्य लक्ष्यों में गरीबी, शिक्षा, स्वास्थ्य तथा पर्यावरण के संकेतक भी सम्मिलित थे।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ग्यारहवीं योजना का विषय \"तीव्रतर और अधिक समावेशी विकास\" था तथा GDP वृद्धि लक्ष्य 9% रखा गया।<br>• अन्य लक्ष्य: गरीबी अनुपात में 10 प्रतिशत बिंदु की कमी, प्रारंभिक शिक्षा में ड्रॉपआउट दर 20% तक, IMR 28 प्रति 1000, MMR 1 प्रति 1000 तथा लिंगानुपात 2011–12 तक 935 तक बढ़ाना।<br>• इसमें वन एवं वृक्ष आवरण 5 प्रतिशत बिंदु बढ़ाने तथा 2009 तक सभी को स्वच्छ पेयजल उपलब्ध कराने के लक्ष्य भी थे।<br>• बारहवीं योजना (2012–17) अंतिम पंचवर्षीय योजना थी; 2015 में योजना आयोग के स्थान पर नीति आयोग आया।"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"MATH":{"seconds":900,"questions":[{"no":51,"local_id":"50051","quid":"Q1000073731","section":"MATH","topic":"Elementary Statistics","question":{"en":"Examine the frequency polygon showing heights of Plants (in cm) in a Garden and answer the following question.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q51.jpg\" style=\"max-width:100%;height:auto\"><br>What is the total number of plants recorded? [SSC CGL 10/10/26 Shift 2]","hi":"बगीचे में पौधों की ऊँचाई (cm में) दर्शाने वाला आवृत्ति बहुभुज देखिए और निम्नलिखित प्रश्न का उत्तर दीजिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q51.jpg\" style=\"max-width:100%;height:auto\"><br>दर्ज कुल पौधों की संख्या क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"75"},"2":{"en":"80"},"3":{"en":"90"},"4":{"en":"85"}},"answer":"2","solution":{"en":"Polygon values: 8, 15, 25, 17, 10, 5<br>Total \\(= 8 + 15 + 25 + 17 + 10 + 5\\)<br>\\(= \\boxed{80}\\)<br><br><b>Hence, the correct answer is option (2): 80.</b>","hi":"बहुभुज के मान: 8, 15, 25, 17, 10, 5<br>कुल \\(= 8 + 15 + 25 + 17 + 10 + 5\\)<br>\\(= \\boxed{80}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 80 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q51.jpg"]}},{"no":52,"local_id":"50052","quid":"Q1000073732","section":"MATH","topic":"Time Speed and Distance","question":{"en":"A man travels 180 km using two modes: bus at 40 km/h and taxi at 60 km/h. If the total journey takes 4 hours, find the distance covered by bus. [SSC CGL 10/10/26 Shift 2]","hi":"एक व्यक्ति 180 km की यात्रा दो साधनों से करता है: बस 40 km/h और टैक्सी 60 km/h से। यदि कुल यात्रा में 4 घंटे लगते हैं, तो बस द्वारा तय की गई दूरी ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"110 km"},"2":{"en":"115 km"},"3":{"en":"120 km"},"4":{"en":"125 km"}},"answer":"3","solution":{"en":"Let bus distance \\(= b\\); \\(\\frac{b}{40} + \\frac{180 - b}{60} = 4\\)<br>\\(3b + 2(180 - b) = 480 \\Rightarrow b = 120\\)<br>\\(= \\boxed{120\\ \\text{km}}\\)<br><br><b>Hence, the correct answer is option (3): 120 km.</b>","hi":"बस की दूरी \\(= b\\) मानिए; \\(\\frac{b}{40} + \\frac{180 - b}{60} = 4\\)<br>\\(3b + 2(180 - b) = 480 \\Rightarrow b = 120\\)<br>\\(= \\boxed{120\\ \\text{km}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 120 km है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":53,"local_id":"50053","quid":"Q1000073733","section":"MATH","topic":"Partnership","question":{"en":"A, B, and C rent a field for ₹5,250. A puts 20 oxen for 4 months, B puts 25 oxen for 2 months, and C puts 30 oxen for 5 months. What part of the rent should B pay? [SSC CGL 10/10/26 Shift 2]","hi":"A, B और C एक खेत ₹5,250 में किराए पर लेते हैं। A 4 माह के लिए 20 बैल, B 2 माह के लिए 25 बैल और C 5 माह के लिए 30 बैल रखता है। B को किराए का कितना भाग देना चाहिए? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"₹850.12"},"2":{"en":"₹920.25"},"3":{"en":"₹750.55"},"4":{"en":"₹937.50"}},"answer":"4","solution":{"en":"Shares: A \\(= 80\\), B \\(= 50\\), C \\(= 150\\) (total 280)<br>B's share \\(= \\frac{50}{280} \\times 5250\\)<br>\\(= \\boxed{937.50}\\)<br><br><b>Hence, the correct answer is option (4): ₹937.50.</b>","hi":"हिस्से: A \\(= 80\\), B \\(= 50\\), C \\(= 150\\) (कुल 280)<br>B का हिस्सा \\(= \\frac{50}{280} \\times 5250\\)<br>\\(= \\boxed{937.50}\\)<br><br><b>अतः सही उत्तर विकल्प (4): ₹937.50 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":54,"local_id":"50054","quid":"Q1000073734","section":"MATH","topic":"Partnership","question":{"en":"A, B, and C start a business with investments in the ratio 3 : 2 : 4. After one year, A withdraws half of his capital and B doubles his capital. After one more year, C withdraws \\(\\frac{1}{4}\\) of his capital. At the end of 3 years, what is the ratio of their profits? [SSC CGL 10/10/26 Shift 2]","hi":"A, B और C 3 : 2 : 4 के अनुपात में निवेश करके व्यवसाय शुरू करते हैं। एक वर्ष बाद A अपनी पूँजी का आधा निकाल लेता है और B अपनी पूँजी दोगुनी कर देता है। एक वर्ष और बाद C अपनी पूँजी का \\(\\frac{1}{4}\\) निकाल लेता है। 3 वर्ष के अंत में उनके लाभ का अनुपात क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"6 : 10 : 11"},"2":{"en":"10 : 18 : 15"},"3":{"en":"9 : 14 : 22"},"4":{"en":"14 : 11 : 19"}},"answer":"1","solution":{"en":"A \\(= 3(1) + 1.5(2) = 6\\)<br>B \\(= 2(1) + 4(2) = 10\\)<br>C \\(= 4(2) + 3(1) = 11\\)<br>Ratio \\(= \\boxed{6 : 10 : 11}\\)<br><br><b>Hence, the correct answer is option (1): 6 : 10 : 11.</b>","hi":"A \\(= 3(1) + 1.5(2) = 6\\)<br>B \\(= 2(1) + 4(2) = 10\\)<br>C \\(= 4(2) + 3(1) = 11\\)<br>अनुपात \\(= \\boxed{6 : 10 : 11}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 6 : 10 : 11 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":55,"local_id":"50055","quid":"Q1000073735","section":"MATH","topic":"Average","question":{"en":"A class of 24 students has an average weight of 35 kg. When the teacher's weight is included, the average increases by 400 grams. Determine the teacher's weight. [SSC CGL 10/10/26 Shift 2]","hi":"24 छात्रों की एक कक्षा का औसत भार 35 kg है। शिक्षक का भार शामिल करने पर औसत 400 ग्राम बढ़ जाता है। शिक्षक का भार ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"45 kg"},"2":{"en":"65 kg"},"3":{"en":"35 kg"},"4":{"en":"55 kg"}},"answer":"1","solution":{"en":"New average \\(= 35.4\\) kg for 25 persons<br>Total \\(= 25 \\times 35.4 = 885\\) kg; students' total \\(= 24 \\times 35 = 840\\)<br>Teacher \\(= 885 - 840 = \\boxed{45\\ \\text{kg}}\\)<br><br><b>Hence, the correct answer is option (1): 45 kg.</b>","hi":"25 व्यक्तियों का नया औसत \\(= 35.4\\) kg<br>कुल \\(= 25 \\times 35.4 = 885\\) kg; छात्रों का कुल \\(= 24 \\times 35 = 840\\)<br>शिक्षक \\(= 885 - 840 = \\boxed{45\\ \\text{kg}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 45 kg है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":56,"local_id":"50056","quid":"Q1000073736","section":"MATH","topic":"Mensuration (2D)","question":{"en":"The side of a regular pentagon is twice the side of a square. If the perimeter of the square is 12 cm, find the perimeter of the pentagon. [SSC CGL 10/10/26 Shift 2]","hi":"एक सम पंचभुज की भुजा एक वर्ग की भुजा की दोगुनी है। यदि वर्ग का परिमाप 12 cm है, तो पंचभुज का परिमाप ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"30 cm"},"2":{"en":"20 cm"},"3":{"en":"35 cm"},"4":{"en":"25 cm"}},"answer":"1","solution":{"en":"Square side \\(= \\frac{12}{4} = 3\\) cm; pentagon side \\(= 6\\) cm<br>Perimeter \\(= 5 \\times 6\\)<br>\\(= \\boxed{30\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (1): 30 cm.</b>","hi":"वर्ग की भुजा \\(= \\frac{12}{4} = 3\\) cm; पंचभुज की भुजा \\(= 6\\) cm<br>परिमाप \\(= 5 \\times 6\\)<br>\\(= \\boxed{30\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 30 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":57,"local_id":"50057","quid":"Q1000073737","section":"MATH","topic":"Profit and Loss","question":{"en":"A manufacturer sells a product at a profit of 40%. If the cost of raw materials increases by 30% and the manufacturer raises the selling price by 20%, what is the new approximate profit percentage? [SSC CGL 10/10/26 Shift 2]","hi":"एक निर्माता कोई उत्पाद 40% लाभ पर बेचता है। यदि कच्चे माल की लागत 30% बढ़ जाए और निर्माता विक्रय मूल्य 20% बढ़ा दे, तो नया अनुमानित लाभ प्रतिशत क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"15%"},"2":{"en":"29%"},"3":{"en":"24%"},"4":{"en":"12%"}},"answer":"2","solution":{"en":"Let CP \\(= 100\\), SP \\(= 140\\)<br>New CP \\(= 130\\), new SP \\(= 168\\)<br>Profit \\(= \\frac{38}{130} \\times 100 \\approx \\boxed{29\\%}\\)<br><br><b>Hence, the correct answer is option (2): 29%.</b>","hi":"मान लीजिए क्रय मूल्य \\(= 100\\), विक्रय मूल्य \\(= 140\\)<br>नया क्रय मूल्य \\(= 130\\), नया विक्रय मूल्य \\(= 168\\)<br>लाभ \\(= \\frac{38}{130} \\times 100 \\approx \\boxed{29\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 29% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":58,"local_id":"50058","quid":"Q1000073738","section":"MATH","topic":"Geometry","question":{"en":"In △PWR, WS ⊥ PR, RT ⊥ PW. WS and RT intersect each other at O. The bisectors of ∠OWR and ∠ORW meet at the same point M. If ∠WPR = 56°, then what is the measure of ∠WMR? [SSC CGL 10/10/26 Shift 2]","hi":"△PWR में, WS ⊥ PR और RT ⊥ PW है। WS और RT एक-दूसरे को O पर प्रतिच्छेद करते हैं। ∠OWR और ∠ORW के समद्विभाजक एक ही बिंदु M पर मिलते हैं। यदि ∠WPR = 56° है, तो ∠WMR का माप क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"152°"},"2":{"en":"178°"},"3":{"en":"180°"},"4":{"en":"118°"}},"answer":"1","solution":{"en":"<svg width=\"273\" height=\"222\" viewBox=\"0 0 273 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M101 26L26 196L247 196ZM26 196L153 87M247 196L62 115M157 91L152 95L148 91M59 120L65 122L67 117M94 41A16 16 0 0 0 111 38\"/><path stroke-dasharray=\"4 3\" d=\"M26 196L106 166L247 196\"/><circle cx=\"106\" cy=\"166\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"98\" y=\"16\">P</text><text x=\"12\" y=\"207\">W</text><text x=\"261\" y=\"206\">R</text><text x=\"160\" y=\"87\">S</text><text x=\"54\" y=\"116\">T</text><text x=\"101\" y=\"126\">O</text><text x=\"106\" y=\"182\">M</text><text x=\"105\" y=\"58\" font-size=\"11\">56°</text></g></svg><br>In quadrilateral \\(WORP\\), \\(\\angle WOR = 180° - 56° = 124°\\)<br>In \\(\\triangle OWR\\): \\(\\angle OWR + \\angle ORW = 180° - 124° = 56°\\)<br>\\(\\angle WMR = 180° - \\frac{56°}{2} = 180° - 28° = \\boxed{152°}\\)<br><br><b>Hence, the correct answer is option (1): 152°.</b>","hi":"<svg width=\"273\" height=\"222\" viewBox=\"0 0 273 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M101 26L26 196L247 196ZM26 196L153 87M247 196L62 115M157 91L152 95L148 91M59 120L65 122L67 117M94 41A16 16 0 0 0 111 38\"/><path stroke-dasharray=\"4 3\" d=\"M26 196L106 166L247 196\"/><circle cx=\"106\" cy=\"166\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"98\" y=\"16\">P</text><text x=\"12\" y=\"207\">W</text><text x=\"261\" y=\"206\">R</text><text x=\"160\" y=\"87\">S</text><text x=\"54\" y=\"116\">T</text><text x=\"101\" y=\"126\">O</text><text x=\"106\" y=\"182\">M</text><text x=\"105\" y=\"58\" font-size=\"11\">56°</text></g></svg><br>चतुर्भुज \\(WORP\\) में \\(\\angle WOR = 180° - 56° = 124°\\)<br>\\(\\triangle OWR\\) में: \\(\\angle OWR + \\angle ORW = 180° - 124° = 56°\\)<br>\\(\\angle WMR = 180° - \\frac{56°}{2} = 180° - 28° = \\boxed{152°}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 152° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":59,"local_id":"50059","quid":"Q1000073739","section":"MATH","topic":"Height and Distance","question":{"en":"A man standing on the roof of a 40 m high building observes the angle of depression of the top and bottom of a nearby pole as 30° and 45°, respectively. Find the height of the pole. [SSC CGL 10/10/26 Shift 2]","hi":"40 m ऊँची इमारत की छत पर खड़ा एक व्यक्ति निकट के खंभे के शिखर और तल के अवनमन कोण क्रमशः 30° और 45° देखता है। खंभे की ऊँचाई ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{30}{\\sqrt{3}}\\) m"},"2":{"en":"\\(40 - \\frac{40}{\\sqrt{3}}\\) m"},"3":{"en":"\\(\\frac{40}{\\sqrt{3}}\\) m"},"4":{"en":"\\(40 - \\frac{30}{\\sqrt{3}}\\) m"}},"answer":"2","solution":{"en":"<svg width=\"242\" height=\"212\" viewBox=\"-17 0 242 212\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 186L199 186M26 186L26 26M186 186L186 118M26 26L186 118M26 26L186 186M34 186L34 178L26 178M70 26A44 44 0 0 1 64 48M46 26A20 20 0 0 1 40 40\"/><path stroke-dasharray=\"4 3\" d=\"M26 26L199 26\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"82\" y=\"45\" font-size=\"11\">30°</text><text x=\"52\" y=\"49\" font-size=\"11\">45°</text><text x=\"14\" y=\"30\">A</text><text x=\"18\" y=\"197\">B</text><text x=\"198\" y=\"122\">C</text><text x=\"194\" y=\"197\">D</text><text x=\"2\" y=\"110\">40 m</text><text x=\"174\" y=\"156\">h</text><text x=\"106\" y=\"202\">d</text></g></svg><br>Bottom: \\(\\tan 45° = \\frac{40}{d} \\Rightarrow d = 40\\) m<br>Top: \\(\\tan 30° = \\frac{40 - h}{40} \\Rightarrow 40 - h = \\frac{40}{\\sqrt{3}}\\)<br>\\(h = \\boxed{40 - \\frac{40}{\\sqrt{3}}\\ \\text{m}}\\)<br><br><b>Hence, the correct answer is option (2): \\(40 - \\frac{40}{\\sqrt{3}}\\) m.</b>","hi":"<svg width=\"242\" height=\"212\" viewBox=\"-17 0 242 212\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 186L199 186M26 186L26 26M186 186L186 118M26 26L186 118M26 26L186 186M34 186L34 178L26 178M70 26A44 44 0 0 1 64 48M46 26A20 20 0 0 1 40 40\"/><path stroke-dasharray=\"4 3\" d=\"M26 26L199 26\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"82\" y=\"45\" font-size=\"11\">30°</text><text x=\"52\" y=\"49\" font-size=\"11\">45°</text><text x=\"14\" y=\"30\">A</text><text x=\"18\" y=\"197\">B</text><text x=\"198\" y=\"122\">C</text><text x=\"194\" y=\"197\">D</text><text x=\"2\" y=\"110\">40 m</text><text x=\"174\" y=\"156\">h</text><text x=\"106\" y=\"202\">d</text></g></svg><br>तल: \\(\\tan 45° = \\frac{40}{d} \\Rightarrow d = 40\\) m<br>शिखर: \\(\\tan 30° = \\frac{40 - h}{40} \\Rightarrow 40 - h = \\frac{40}{\\sqrt{3}}\\)<br>\\(h = \\boxed{40 - \\frac{40}{\\sqrt{3}}\\ \\text{m}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): \\(40 - \\frac{40}{\\sqrt{3}}\\) m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":60,"local_id":"50060","quid":"Q1000073740","section":"MATH","topic":"Mensuration (2D)","question":{"en":"The area of a square is 144 cm². A circle is inscribed inside the square. What is the area of another square inscribed inside this circle? [SSC CGL 10/10/26 Shift 2]","hi":"एक वर्ग का क्षेत्रफल 144 cm² है। इस वर्ग के अंदर एक वृत्त अंतर्निहित है। इस वृत्त के अंदर अंतर्निहित दूसरे वर्ग का क्षेत्रफल क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"36 cm²"},"2":{"en":"54 cm²"},"3":{"en":"72 cm²"},"4":{"en":"108 cm²"}},"answer":"3","solution":{"en":"<svg width=\"212\" height=\"212\" viewBox=\"0 0 212 212\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 186L186 186L186 26L26 26ZM186 106L106 26L26 106L106 186Z\"/><path stroke-dasharray=\"4 3\" d=\"M26 106L186 106\"/><circle cx=\"106\" cy=\"106\" r=\"80\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"106\" y=\"202\">12 cm</text><text x=\"142\" y=\"98\" font-size=\"11\">d = 12</text></g></svg><br>Square side \\(= 12\\), circle diameter \\(= 12\\), radius \\(= 6\\)<br>Inner square diagonal \\(= 12 = a\\sqrt{2} \\Rightarrow a^2 = \\frac{144}{2}\\)<br>\\(= \\boxed{72\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (3): 72 cm².</b>","hi":"<svg width=\"212\" height=\"212\" viewBox=\"0 0 212 212\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 186L186 186L186 26L26 26ZM186 106L106 26L26 106L106 186Z\"/><path stroke-dasharray=\"4 3\" d=\"M26 106L186 106\"/><circle cx=\"106\" cy=\"106\" r=\"80\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"106\" y=\"202\">12 cm</text><text x=\"142\" y=\"98\" font-size=\"11\">d = 12</text></g></svg><br>वर्ग की भुजा \\(= 12\\), वृत्त का व्यास \\(= 12\\), त्रिज्या \\(= 6\\)<br>अंदरूनी वर्ग का विकर्ण \\(= 12 = a\\sqrt{2} \\Rightarrow a^2 = \\frac{144}{2}\\)<br>\\(= \\boxed{72\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 72 cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":61,"local_id":"50061","quid":"Q1000073741","section":"MATH","topic":"Trigonometry","question":{"en":"If 3 sinθ − 4 cosθ = 0, where 0° < θ < 90°, find \\(\\frac{3\\sin\\theta + \\cos\\theta}{3\\sin\\theta + 2\\cos\\theta}\\). [SSC CGL 10/10/26 Shift 2]","hi":"यदि 3 sinθ − 4 cosθ = 0 है, जहाँ 0° < θ < 90°, तो \\(\\frac{3\\sin\\theta + \\cos\\theta}{3\\sin\\theta + 2\\cos\\theta}\\) ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{6}{5}\\)"},"2":{"en":"\\(\\frac{18}{5}\\)"},"3":{"en":"\\(\\frac{5}{6}\\)"},"4":{"en":"\\(\\frac{5}{18}\\)"}},"answer":"3","solution":{"en":"\\(\\tan\\theta = \\frac{4}{3}\\); put \\(\\sin\\theta = 4k\\), \\(\\cos\\theta = 3k\\)<br>\\(\\frac{12k + 3k}{12k + 6k} = \\frac{15}{18}\\)<br>\\(= \\boxed{\\frac{5}{6}}\\)<br><br><b>Hence, the correct answer is option (3): \\(\\frac{5}{6}\\).</b>","hi":"\\(\\tan\\theta = \\frac{4}{3}\\); \\(\\sin\\theta = 4k\\), \\(\\cos\\theta = 3k\\) रखिए<br>\\(\\frac{12k + 3k}{12k + 6k} = \\frac{15}{18}\\)<br>\\(= \\boxed{\\frac{5}{6}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): \\(\\frac{5}{6}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":62,"local_id":"50062","quid":"Q1000073742","section":"MATH","topic":"Trigonometry","question":{"en":"Evaluate the following expression:<br>\\(\\frac{4}{3}\\cot^2 30° + 3\\sin^2 60° - 2\\operatorname{cosec}^2 60° - \\frac{3}{4}\\tan^2 30°\\) [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित व्यंजक का मान ज्ञात कीजिए:<br>\\(\\frac{4}{3}\\cot^2 30° + 3\\sin^2 60° - 2\\operatorname{cosec}^2 60° - \\frac{3}{4}\\tan^2 30°\\) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{8}{3}\\)"},"2":{"en":"\\(\\frac{14}{3}\\)"},"3":{"en":"\\(\\frac{4}{3}\\)"},"4":{"en":"\\(\\frac{10}{3}\\)"}},"answer":"4","solution":{"en":"\\(\\frac{4}{3}(3) + 3\\left(\\frac{3}{4}\\right) - 2\\left(\\frac{4}{3}\\right) - \\frac{3}{4}\\left(\\frac{1}{3}\\right)\\)<br>\\(= 4 + \\frac{9}{4} - \\frac{8}{3} - \\frac{1}{4}\\)<br>\\(= \\boxed{\\frac{10}{3}}\\)<br><br><b>Hence, the correct answer is option (4): \\(\\frac{10}{3}\\).</b>","hi":"\\(\\frac{4}{3}(3) + 3\\left(\\frac{3}{4}\\right) - 2\\left(\\frac{4}{3}\\right) - \\frac{3}{4}\\left(\\frac{1}{3}\\right)\\)<br>\\(= 4 + \\frac{9}{4} - \\frac{8}{3} - \\frac{1}{4}\\)<br>\\(= \\boxed{\\frac{10}{3}}\\)<br><br><b>अतः सही उत्तर विकल्प (4): \\(\\frac{10}{3}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":63,"local_id":"50063","quid":"Q1000073743","section":"MATH","topic":"Algebra","question":{"en":"If \\(\\frac{\\sqrt{7+X} + \\sqrt{7-X}}{\\sqrt{7+X} - \\sqrt{7-X}} = 5\\), then what is the value of X? [SSC CGL 10/10/26 Shift 2]","hi":"यदि \\(\\frac{\\sqrt{7+X} + \\sqrt{7-X}}{\\sqrt{7+X} - \\sqrt{7-X}} = 5\\) है, तो X का मान क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{1}{2}\\)"},"2":{"en":"\\(\\frac{35}{13}\\)"},"3":{"en":"\\(\\frac{3}{2}\\)"},"4":{"en":"\\(\\frac{14}{19}\\)"}},"answer":"2","solution":{"en":"Using componendo–dividendo: \\(\\frac{2\\sqrt{7+X}}{2\\sqrt{7-X}} = \\frac{6}{4}\\)<br>\\(\\frac{7+X}{7-X} = \\frac{9}{4}\\)<br>\\(28 + 4X = 63 - 9X \\Rightarrow X = \\frac{35}{13}\\): \\(\\boxed{\\frac{35}{13}}\\)<br><br><b>Hence, the correct answer is option (2): \\(\\frac{35}{13}\\).</b>","hi":"योगानुपात-अंतरानुपात से: \\(\\frac{2\\sqrt{7+X}}{2\\sqrt{7-X}} = \\frac{6}{4}\\)<br>\\(\\frac{7+X}{7-X} = \\frac{9}{4}\\)<br>\\(28 + 4X = 63 - 9X \\Rightarrow X = \\frac{35}{13}\\): \\(\\boxed{\\frac{35}{13}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): \\(\\frac{35}{13}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":64,"local_id":"50064","quid":"Q1000073744","section":"MATH","topic":"Elementary Statistics","question":{"en":"Read the following histogram carefully which represents the spending (in USD) on the x-axis and the number of customers (frequency) on the y-axis, and answer the question that follows:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q64.jpg\" style=\"max-width:100%;height:auto\"><br>What percentage of customers spend more than USD 150 compared to those who spend less than USD 50? (Answer correct to one decimal place) [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित आयतचित्र ध्यान से पढ़िए जिसमें x-अक्ष पर खर्च (USD में) और y-अक्ष पर ग्राहकों की संख्या (आवृत्ति) दी गई है, और अगले प्रश्न का उत्तर दीजिए:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q64.jpg\" style=\"max-width:100%;height:auto\"><br>USD 150 से अधिक खर्च करने वाले ग्राहक, USD 50 से कम खर्च करने वाले ग्राहकों की तुलना में कितने प्रतिशत हैं? (एक दशमलव स्थान तक) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"40%"},"2":{"en":"55%"},"3":{"en":"60%"},"4":{"en":"75%"}},"answer":"3","solution":{"en":"Frequencies: 30, 45, 7, 3, 15 (total 100)<br>More than 150: \\(3 + 15 = 18\\); less than 50: \\(30\\)<br>\\(\\frac{18}{30} \\times 100 = \\boxed{60\\%}\\)<br><br><b>Hence, the correct answer is option (3): 60%.</b>","hi":"आवृत्तियाँ: 30, 45, 7, 3, 15 (कुल 100)<br>150 से अधिक: \\(3 + 15 = 18\\); 50 से कम: \\(30\\)<br>\\(\\frac{18}{30} \\times 100 = \\boxed{60\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 60% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q64.jpg"]}},{"no":65,"local_id":"50065","quid":"Q1000073745","section":"MATH","topic":"Discount","question":{"en":"The marked price of an article is ₹800. It is sold for ₹612.50 after two successive discounts of x% each. If instead a single discount of 2x% is applied on the same marked price, find the selling price of the article. [SSC CGL 10/10/26 Shift 2]","hi":"एक वस्तु का अंकित मूल्य ₹800 है। इसे x% की दो क्रमिक छूटों के बाद ₹612.50 में बेचा जाता है। यदि उसी अंकित मूल्य पर 2x% की एकल छूट दी जाए, तो वस्तु का विक्रय मूल्य ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"₹540"},"2":{"en":"₹600"},"3":{"en":"₹660"},"4":{"en":"₹700"}},"answer":"2","solution":{"en":"\\(800(1 - x)^2 = 612.5 \\Rightarrow (1 - x)^2 = 0.765625\\)<br>\\(1 - x = 0.875 \\Rightarrow x = 12.5\\%\\), so \\(2x = 25\\%\\)<br>SP \\(= 0.75 \\times 800 = \\boxed{600}\\)<br><br><b>Hence, the correct answer is option (2): ₹600.</b>","hi":"\\(800(1 - x)^2 = 612.5 \\Rightarrow (1 - x)^2 = 0.765625\\)<br>\\(1 - x = 0.875 \\Rightarrow x = 12.5\\%\\), अतः \\(2x = 25\\%\\)<br>विक्रय मूल्य \\(= 0.75 \\times 800 = \\boxed{600}\\)<br><br><b>अतः सही उत्तर विकल्प (2): ₹600 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":66,"local_id":"50066","quid":"Q1000073746","section":"MATH","topic":"Discount","question":{"en":"A trader makes a profit of ₹100 on selling an item after allowing a discount of 20%. If the profit is 25%, find the marked price of the item. [SSC CGL 10/10/26 Shift 2]","hi":"एक व्यापारी किसी वस्तु को 20% छूट देकर बेचने पर ₹100 का लाभ कमाता है। यदि लाभ 25% है, तो वस्तु का अंकित मूल्य ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"₹475"},"2":{"en":"₹530"},"3":{"en":"₹710"},"4":{"en":"₹625"}},"answer":"4","solution":{"en":"Profit 25% of CP \\(= 100 \\Rightarrow\\) CP \\(= 400\\), SP \\(= 500\\)<br>\\(500 = 0.8 \\times\\) MP<br>MP \\(= \\boxed{625}\\)<br><br><b>Hence, the correct answer is option (4): ₹625.</b>","hi":"क्रय मूल्य का 25% लाभ \\(= 100 \\Rightarrow\\) क्रय मूल्य \\(= 400\\), विक्रय मूल्य \\(= 500\\)<br>\\(500 = 0.8 \\times\\) अंकित मूल्य<br>अंकित मूल्य \\(= \\boxed{625}\\)<br><br><b>अतः सही उत्तर विकल्प (4): ₹625 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":67,"local_id":"50067","quid":"Q1000073747","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"The following pie-chart represents the percentage-wise market share held by five different brands. Study the pie-chart carefully and answer the question based on it.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q67.jpg\" style=\"max-width:100%;height:auto\"><br>If the total annual revenue of the market is ₹50,00,000, what is the difference in revenue between Brand A and the combined revenue of Brand D and Brand E? [SSC CGL 10/10/26 Shift 2]","hi":"निम्नलिखित पाई चार्ट पाँच अलग-अलग ब्रांडों की प्रतिशत-वार बाज़ार हिस्सेदारी दर्शाता है। पाई चार्ट का ध्यान से अध्ययन कीजिए और उसके आधार पर प्रश्न का उत्तर दीजिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q67.jpg\" style=\"max-width:100%;height:auto\"><br>यदि बाज़ार का कुल वार्षिक राजस्व ₹50,00,000 है, तो ब्रांड A के राजस्व और ब्रांड D तथा ब्रांड E के संयुक्त राजस्व का अंतर क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"₹5,00,000"},"2":{"en":"₹2,50,000"},"3":{"en":"₹5,50,000"},"4":{"en":"₹2,00,000"}},"answer":"2","solution":{"en":"Brand A \\(= 30\\%\\), D + E \\(= 15\\% + 10\\% = 25\\%\\)<br>Difference \\(= 5\\%\\) of 50,00,000<br>\\(= \\boxed{2{,}50{,}000}\\)<br><br><b>Hence, the correct answer is option (2): ₹2,50,000.</b>","hi":"ब्रांड A \\(= 30\\%\\), D + E \\(= 15\\% + 10\\% = 25\\%\\)<br>अंतर \\(= 50{,}00{,}000\\) का 5%<br>\\(= \\boxed{2{,}50{,}000}\\)<br><br><b>अतः सही उत्तर विकल्प (2): ₹2,50,000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q67.jpg"]}},{"no":68,"local_id":"50068","quid":"Q1000073748","section":"MATH","topic":"Set Relation and Function","question":{"en":"Which of the following is a correct statement about the Cantor set C ⊂ [0, 1]? [SSC CGL 10/10/26 Shift 2]","hi":"कैंटर समुच्चय C ⊂ [0, 1] के बारे में निम्नलिखित में से कौन-सा कथन सही है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"C is countable and has measure 1","hi":"C गणनीय है और इसका माप 1 है"},"2":{"en":"C is uncountable and has measure 0","hi":"C अगणनीय है और इसका माप 0 है"},"3":{"en":"C is countable and has measure 0","hi":"C गणनीय है और इसका माप 0 है"},"4":{"en":"C is uncountable and has measure 1/3","hi":"C अगणनीय है और इसका माप 1/3 है"}},"answer":"2","solution":{"en":"The Cantor set is uncountable (it has the cardinality of the continuum) yet has total length (measure) 0<br>\\(\\boxed{\\text{C is uncountable and has measure 0}}\\)<br><br><b>Hence, the correct answer is option (2): C is uncountable and has measure 0.</b>","hi":"कैंटर समुच्चय अगणनीय है (इसकी गणनसंख्या सांतत्य के बराबर है), फिर भी इसका कुल माप 0 है<br>\\(\\boxed{\\text{C अगणनीय है और इसका माप 0 है}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): C अगणनीय है और इसका माप 0 है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":69,"local_id":"50069","quid":"Q1000073749","section":"MATH","topic":"Number System","question":{"en":"The difference between the squares of two consecutive positive integers is 47. What is the smaller integer? [SSC CGL 10/10/26 Shift 2]","hi":"दो क्रमागत धनात्मक पूर्णांकों के वर्गों का अंतर 47 है। छोटा पूर्णांक क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"23"},"2":{"en":"25"},"3":{"en":"35"},"4":{"en":"41"}},"answer":"1","solution":{"en":"\\((n+1)^2 - n^2 = 2n + 1 = 47\\)<br>\\(n = 23\\)<br>\\(= \\boxed{23}\\)<br><br><b>Hence, the correct answer is option (1): 23.</b>","hi":"\\((n+1)^2 - n^2 = 2n + 1 = 47\\)<br>\\(n = 23\\)<br>\\(= \\boxed{23}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 23 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":70,"local_id":"50070","quid":"Q1000073750","section":"MATH","topic":"Ratio and Proportion","question":{"en":"Three siblings, namely Kamal, Rupa and Drishti, have different amounts of money with them which add up to Rs. 66000. On a particular day, they decide to go shopping and spend 54%, 40% and \\(66\\frac{2}{3}\\%\\) from their individual amounts, respectively. If the ratio of the amounts of money left with them after shopping, respectively, is 23:33:20, how much money did Drishti have before shopping? [SSC CGL 10/10/26 Shift 2]","hi":"तीन भाई-बहन कमल, रूपा और दृष्टि के पास अलग-अलग मात्रा में धन है जिसका योग Rs. 66000 है। एक विशेष दिन वे खरीदारी करने जाते हैं और अपनी व्यक्तिगत राशि से क्रमशः 54%, 40% और \\(66\\frac{2}{3}\\%\\) खर्च करते हैं। यदि खरीदारी के बाद उनके पास बची राशियों का अनुपात क्रमशः 23:33:20 है, तो खरीदारी से पहले दृष्टि के पास कितना धन था? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Rs. 20000"},"2":{"en":"Rs. 22000"},"3":{"en":"Rs. 24000"},"4":{"en":"Rs. 26000"}},"answer":"3","solution":{"en":"Left percentages: Kamal 46%, Rupa 60%, Drishti \\(33\\frac{1}{3}\\%\\)<br>\\(0.46K : 0.60R : \\frac{1}{3}D = 23 : 33 : 20\\)<br>\\(K = 50x\\), \\(R = 55x\\), \\(D = 60x\\); total \\(165x = 66000 \\Rightarrow x = 400\\)<br>Drishti \\(= 60 \\times 400 = \\boxed{24{,}000}\\)<br><br><b>Hence, the correct answer is option (3): Rs. 24000.</b>","hi":"शेष प्रतिशत: कमल 46%, रूपा 60%, दृष्टि \\(33\\frac{1}{3}\\%\\)<br>\\(0.46K : 0.60R : \\frac{1}{3}D = 23 : 33 : 20\\)<br>\\(K = 50x\\), \\(R = 55x\\), \\(D = 60x\\); कुल \\(165x = 66000 \\Rightarrow x = 400\\)<br>दृष्टि \\(= 60 \\times 400 = \\boxed{24{,}000}\\)<br><br><b>अतः सही उत्तर विकल्प (3): Rs. 24000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":71,"local_id":"50071","quid":"Q1000073751","section":"MATH","topic":"Algebra","question":{"en":"In the expansion of the trinomial square (2x − 3y + 4z)², what is the sum of the coefficients of the xy and yz terms? [SSC CGL 10/10/26 Shift 2]","hi":"त्रिपद वर्ग (2x − 3y + 4z)² के प्रसार में xy और yz पदों के गुणांकों का योग क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"−6"},"2":{"en":"18"},"3":{"en":"−36"},"4":{"en":"12"}},"answer":"3","solution":{"en":"Cross terms: \\(2(2x)(-3y) = -12xy\\), \\(2(-3y)(4z) = -24yz\\)<br>Sum \\(= -12 + (-24)\\)<br>\\(= \\boxed{-36}\\)<br><br><b>Hence, the correct answer is option (3): −36.</b>","hi":"क्रॉस पद: \\(2(2x)(-3y) = -12xy\\), \\(2(-3y)(4z) = -24yz\\)<br>योग \\(= -12 + (-24)\\)<br>\\(= \\boxed{-36}\\)<br><br><b>अतः सही उत्तर विकल्प (3): −36 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":72,"local_id":"50072","quid":"Q1000073752","section":"MATH","topic":"Algebra","question":{"en":"Find the value of \\((8a + 5b)^2 - (8a - 5b)^2\\). [SSC CGL 10/10/26 Shift 2]","hi":"\\((8a + 5b)^2 - (8a - 5b)^2\\) का मान ज्ञात कीजिए। [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"16ab"},"2":{"en":"80ab"},"3":{"en":"\\(128a^2 + 50b^2\\)"},"4":{"en":"160ab"}},"answer":"4","solution":{"en":"\\((x+y)^2 - (x-y)^2 = 4xy\\) with \\(x = 8a\\), \\(y = 5b\\)<br>\\(= 4 \\times 8a \\times 5b\\)<br>\\(= \\boxed{160ab}\\)<br><br><b>Hence, the correct answer is option (4): 160ab.</b>","hi":"\\((x+y)^2 - (x-y)^2 = 4xy\\), जहाँ \\(x = 8a\\), \\(y = 5b\\)<br>\\(= 4 \\times 8a \\times 5b\\)<br>\\(= \\boxed{160ab}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 160ab है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":73,"local_id":"50073","quid":"Q1000073753","section":"MATH","topic":"Average","question":{"en":"The average weight of 15 players in a cricket team is 68 kg. If the captain, whose weight is 80 kg, is replaced by a new player, the average weight of the team drops by 0.8 kg. What is the weight of the new player? [SSC CGL 10/10/26 Shift 2]","hi":"एक क्रिकेट टीम के 15 खिलाड़ियों का औसत भार 68 kg है। यदि 80 kg भार वाले कप्तान के स्थान पर एक नया खिलाड़ी लिया जाए, तो टीम का औसत भार 0.8 kg घट जाता है। नए खिलाड़ी का भार क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"56 kg"},"2":{"en":"68 kg"},"3":{"en":"72 kg"},"4":{"en":"92 kg"}},"answer":"2","solution":{"en":"Total drop \\(= 0.8 \\times 15 = 12\\) kg<br>New weight \\(= 80 - 12\\)<br>\\(= \\boxed{68\\ \\text{kg}}\\)<br><br><b>Hence, the correct answer is option (2): 68 kg.</b>","hi":"कुल कमी \\(= 0.8 \\times 15 = 12\\) kg<br>नया भार \\(= 80 - 12\\)<br>\\(= \\boxed{68\\ \\text{kg}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 68 kg है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":74,"local_id":"50074","quid":"Q1000073754","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"An electronics store compared the sales of two brands of smartphones, Brand A and Brand B over the first four months of a calendar year. The observations are illustrated below in the given bar graph:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q74.jpg\" style=\"max-width:100%;height:auto\"><br>What is the average monthly sales volume for Brand B across the four months? [SSC CGL 10/10/26 Shift 2]","hi":"एक इलेक्ट्रॉनिक्स स्टोर ने कैलेंडर वर्ष के पहले चार महीनों में दो स्मार्टफोन ब्रांडों, ब्रांड A और ब्रांड B की बिक्री की तुलना की। अवलोकन नीचे दिए बार ग्राफ में दर्शाए गए हैं:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q74.jpg\" style=\"max-width:100%;height:auto\"><br>चार महीनों में ब्रांड B की औसत मासिक बिक्री मात्रा क्या है? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"120 units"},"2":{"en":"125 units"},"3":{"en":"130 units"},"4":{"en":"135 units"}},"answer":"2","solution":{"en":"Brand B bars: 95, 110, 135, 160<br>Average \\(= \\frac{95 + 110 + 135 + 160}{4}\\)<br>\\(= \\boxed{125\\ \\text{units}}\\)<br><br><b>Hence, the correct answer is option (2): 125 units.</b>","hi":"ब्रांड B के बार: 95, 110, 135, 160<br>औसत \\(= \\frac{95 + 110 + 135 + 160}{4}\\)<br>\\(= \\boxed{125\\ \\text{units}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 125 units है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-10-OCT-2026-SHIFT-2/q74.jpg"]}},{"no":75,"local_id":"50075","quid":"Q1000073755","section":"MATH","topic":"Percentage","question":{"en":"In a three-candidate election, 90% of registered voters vote and 4% of votes cast are invalid. Initially, the winner, runner-up and third candidate receive 45%, 35% and 20% of valid votes. If 10% of the third candidate's votes are transferred to the runner-up, the winner's lead becomes 5,184 votes. How many voters are registered? [SSC CGL 10/10/26 Shift 2]","hi":"तीन उम्मीदवारों वाले चुनाव में पंजीकृत मतदाताओं के 90% मत डालते हैं और डाले गए मतों के 4% अवैध होते हैं। प्रारंभ में विजेता, दूसरे स्थान के उम्मीदवार और तीसरे उम्मीदवार को वैध मतों के 45%, 35% और 20% मिलते हैं। यदि तीसरे उम्मीदवार के 10% मत दूसरे स्थान के उम्मीदवार को स्थानांतरित हो जाएँ, तो विजेता की बढ़त 5,184 मत हो जाती है। कितने मतदाता पंजीकृत हैं? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"70,000"},"2":{"en":"72,000"},"3":{"en":"75,000"},"4":{"en":"80,000"}},"answer":"3","solution":{"en":"Let registered voters be \\(N\\); valid votes \\(= 0.9N \\times 0.96 = 0.864N\\)<br>Winner \\(45\\%\\), runner-up becomes \\(35\\% + 2\\% = 37\\%\\)<br>Lead \\(= 8\\%\\) of valid \\(= 0.08 \\times 0.864N = 0.06912N = 5184\\)<br>\\(N = \\boxed{75{,}000}\\)<br><br><b>Hence, the correct answer is option (3): 75,000.</b>","hi":"पंजीकृत मतदाता \\(N\\); वैध मत \\(= 0.9N \\times 0.96 = 0.864N\\)<br>विजेता \\(45\\%\\), दूसरा उम्मीदवार \\(35\\% + 2\\% = 37\\%\\)<br>बढ़त \\(= \\) वैध मतों का 8% \\(= 0.08 \\times 0.864N = 0.06912N = 5184\\)<br>\\(N = \\boxed{75{,}000}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 75,000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"ENGLISH":{"seconds":900,"questions":[{"no":76,"local_id":"50076","quid":"Q1000073756","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the following question, a sentence with a blank is given, followed by five words labeled (1), (2), (3), (4), and (5). Choose the word that fills the blank appropriately in the context of the passage.<br><br>In a world increasingly dominated by constant connectivity, the practice of deliberate solitude (1)___ a counterbalance to the cognitive overload many experience daily. Contrary to the pervasive notion that being alone equates to loneliness, solitude (2)___ a fertile ground for introspection, creativity, and emotional recalibration. Engaging in solitary reflection enables individuals to disentangle themselves from external validation, thereby fostering a more (3)___ autonomous sense of self.<br><br>Neurological studies have revealed that periods of intentional solitude stimulate the brain’s default mode network — a system linked to memory consolidation, future planning, and self-referential thought. However, the benefits of solitude are contingent upon mindset; when chosen voluntarily, it (4)___ restorative, but when imposed, it can exacerbate feelings of isolation. Moreover, solitude encourages metacognition, the ability to think about one’s own thinking, thereby enhancing problem-solving skills and emotional regulation.<br><br>In broader philosophical discourse, solitude is often celebrated as a medium for existential (5)___ rumination.<br><br>Thus, rather than being perceived as a void, solitude should be embraced as an opportunity for profound personal growth and inner clarity.<br><br><br>Choose correct verb to complete tense. (1) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"provides"},"2":{"en":"is providing"},"3":{"en":"provided"},"4":{"en":"had provided"}},"answer":"1","solution":{"en":"<b>Rule: Simple present states a general benefit.</b><br>The singular subject “the practice” takes “provides.”<br>Deliberate solitude generally provides a counterbalance to cognitive overload.<br>Present continuous is unnecessary; simple past and past perfect conflict with the passage’s present discussion.<br><br><b>Hence, the correct answer is option (1): provides.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":77,"local_id":"50077","quid":"Q1000073757","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the following question, a sentence with a blank is given, followed by five words labeled (1), (2), (3), (4), and (5). Choose the word that fills the blank appropriately in the context of the passage.<br><br>In a world increasingly dominated by constant connectivity, the practice of deliberate solitude (1)___ a counterbalance to the cognitive overload many experience daily. Contrary to the pervasive notion that being alone equates to loneliness, solitude (2)___ a fertile ground for introspection, creativity, and emotional recalibration. Engaging in solitary reflection enables individuals to disentangle themselves from external validation, thereby fostering a more (3)___ autonomous sense of self.<br><br>Neurological studies have revealed that periods of intentional solitude stimulate the brain’s default mode network — a system linked to memory consolidation, future planning, and self-referential thought. However, the benefits of solitude are contingent upon mindset; when chosen voluntarily, it (4)___ restorative, but when imposed, it can exacerbate feelings of isolation. Moreover, solitude encourages metacognition, the ability to think about one’s own thinking, thereby enhancing problem-solving skills and emotional regulation.<br><br>In broader philosophical discourse, solitude is often celebrated as a medium for existential (5)___ rumination.<br><br>Thus, rather than being perceived as a void, solitude should be embraced as an opportunity for profound personal growth and inner clarity.<br><br><br>Focus on article + verb agreement. (2) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"offer"},"2":{"en":"offers"},"3":{"en":"offered"},"4":{"en":"offering"}},"answer":"2","solution":{"en":"<b>Rule: Singular “solitude” takes the singular present verb “offers.”</b><br>The passage describes a general quality of solitude.<br>“Offer” lacks singular agreement, “offered” shifts to the past, and “offering” cannot be the finite verb.<br>The article “a” before “fertile ground” is already correctly supplied.<br><br><b>Hence, the correct answer is option (2): offers.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":78,"local_id":"50078","quid":"Q1000073758","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the following question, a sentence with a blank is given, followed by five words labeled (1), (2), (3), (4), and (5). Choose the word that fills the blank appropriately in the context of the passage.<br><br>In a world increasingly dominated by constant connectivity, the practice of deliberate solitude (1)___ a counterbalance to the cognitive overload many experience daily. Contrary to the pervasive notion that being alone equates to loneliness, solitude (2)___ a fertile ground for introspection, creativity, and emotional recalibration. Engaging in solitary reflection enables individuals to disentangle themselves from external validation, thereby fostering a more (3)___ autonomous sense of self.<br><br>Neurological studies have revealed that periods of intentional solitude stimulate the brain’s default mode network — a system linked to memory consolidation, future planning, and self-referential thought. However, the benefits of solitude are contingent upon mindset; when chosen voluntarily, it (4)___ restorative, but when imposed, it can exacerbate feelings of isolation. Moreover, solitude encourages metacognition, the ability to think about one’s own thinking, thereby enhancing problem-solving skills and emotional regulation.<br><br>In broader philosophical discourse, solitude is often celebrated as a medium for existential (5)___ rumination.<br><br>Thus, rather than being perceived as a void, solitude should be embraced as an opportunity for profound personal growth and inner clarity.<br><br><br>In this context, “autonomous” most nearly means: (3) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Dependent on others"},"2":{"en":"Self-governing and independent"},"3":{"en":"Socially driven"},"4":{"en":"Emotionally unstable"}},"answer":"2","solution":{"en":"<b>Autonomous (स्वायत्त) = self-governing and independent.</b><br>Solitude helps individuals rely less on external validation and develop an independent identity.<br>Dependence on others and being socially driven are contrary to this idea.<br>Emotional instability is unrelated to self-governance.<br><br><b>Hence, the correct answer is option (2): Self-governing and independent.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":79,"local_id":"50079","quid":"Q1000073759","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the following question, a sentence with a blank is given, followed by five words labeled (1), (2), (3), (4), and (5). Choose the word that fills the blank appropriately in the context of the passage.<br><br>In a world increasingly dominated by constant connectivity, the practice of deliberate solitude (1)___ a counterbalance to the cognitive overload many experience daily. Contrary to the pervasive notion that being alone equates to loneliness, solitude (2)___ a fertile ground for introspection, creativity, and emotional recalibration. Engaging in solitary reflection enables individuals to disentangle themselves from external validation, thereby fostering a more (3)___ autonomous sense of self.<br><br>Neurological studies have revealed that periods of intentional solitude stimulate the brain’s default mode network — a system linked to memory consolidation, future planning, and self-referential thought. However, the benefits of solitude are contingent upon mindset; when chosen voluntarily, it (4)___ restorative, but when imposed, it can exacerbate feelings of isolation. Moreover, solitude encourages metacognition, the ability to think about one’s own thinking, thereby enhancing problem-solving skills and emotional regulation.<br><br>In broader philosophical discourse, solitude is often celebrated as a medium for existential (5)___ rumination.<br><br>Thus, rather than being perceived as a void, solitude should be embraced as an opportunity for profound personal growth and inner clarity.<br><br><br>Choose best pronoun consistency/verb form. (4) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"is being"},"2":{"en":"has been"},"3":{"en":"is"},"4":{"en":"would have been"}},"answer":"3","solution":{"en":"<b>Rule: Simple present expresses the conditional general result.</b><br>The pronoun “it” refers to solitude, and the singular verb “is” links it to “restorative.”<br>“When chosen voluntarily, it <b>is</b> restorative” parallels “when imposed, it can exacerbate ….”<br>The other options introduce unnecessary continuous, perfect or hypothetical forms.<br><br><b>Hence, the correct answer is option (3): is.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":80,"local_id":"50080","quid":"Q1000073760","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the following question, a sentence with a blank is given, followed by five words labeled (1), (2), (3), (4), and (5). Choose the word that fills the blank appropriately in the context of the passage.<br><br>In a world increasingly dominated by constant connectivity, the practice of deliberate solitude (1)___ a counterbalance to the cognitive overload many experience daily. Contrary to the pervasive notion that being alone equates to loneliness, solitude (2)___ a fertile ground for introspection, creativity, and emotional recalibration. Engaging in solitary reflection enables individuals to disentangle themselves from external validation, thereby fostering a more (3)___ autonomous sense of self.<br><br>Neurological studies have revealed that periods of intentional solitude stimulate the brain’s default mode network — a system linked to memory consolidation, future planning, and self-referential thought. However, the benefits of solitude are contingent upon mindset; when chosen voluntarily, it (4)___ restorative, but when imposed, it can exacerbate feelings of isolation. Moreover, solitude encourages metacognition, the ability to think about one’s own thinking, thereby enhancing problem-solving skills and emotional regulation.<br><br>In broader philosophical discourse, solitude is often celebrated as a medium for existential (5)___ rumination.<br><br>Thus, rather than being perceived as a void, solitude should be embraced as an opportunity for profound personal growth and inner clarity.<br><br><br>The word “rumination” most nearly means: (5) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Casual amusement"},"2":{"en":"Rapid decision-making"},"3":{"en":"Deep, prolonged thought"},"4":{"en":"Immediate physical reaction"}},"answer":"3","solution":{"en":"<b>Rumination (चिंतन, गहन विचार) = deep and prolonged thought.</b><br>Existential rumination involves sustained reflection on existence and personal meaning.<br>Casual amusement lacks this depth; rapid decisions and immediate physical reactions are not contemplation.<br><br><b>Hence, the correct answer is option (3): Deep, prolonged thought.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":81,"local_id":"50081","quid":"Q1000073761","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct indirect speech form of the following sentence.<br>He said, “May I come in?” [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"He asked if he may come in."},"2":{"en":"He asked whether he can come in."},"3":{"en":"He asked if he might come in."},"4":{"en":"He told if he could come in."}},"answer":"3","solution":{"en":"<b>Rule: Report a permission-seeking question with “asked if/whether,” and change “may” to “might.”</b><br>“I” becomes “he.”<br>A retains “may”; B changes to “can,” expressing ability rather than permission.<br>D incorrectly uses “told” instead of “asked.”<br><br><b>Hence, the correct answer is option (3): He asked if he might come in.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":82,"local_id":"50082","quid":"Q1000073762","section":"ENGLISH","topic":"Phrasal Verbs","question":{"en":"Complete the collacation by choosing a suitable word to fill in the blank.<br>The scientist was able to ___ a theory that explained the phenomenon. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"put forward"},"2":{"en":"invent"},"3":{"en":"bring out"},"4":{"en":"bring forward"}},"answer":"1","solution":{"en":"<b>Put forward (प्रस्तुत करना) = propose an idea or theory for consideration.</b><br>A scientist puts forward a theory explaining a phenomenon.<br>“Invent” suggests creating something unreal; “bring out” means publish or emphasize.<br>“Bring forward” can mean reschedule or introduce evidence but is less natural here.<br><br><b>Hence, the correct answer is option (1): put forward.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":83,"local_id":"50083","quid":"Q1000073763","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blanks with appropriate parts of speech.<br>The director's ___ refusal to compromise and the board's ___ criticism led to a stalemate. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"steadiness, scathing"},"2":{"en":"steadfastly, scathe"},"3":{"en":"steadfast, scathing"},"4":{"en":"steadily, scathes"}},"answer":"3","solution":{"en":"<b>Rule: Adjectives modify the nouns “refusal” and “criticism.”</b><br>“Steadfast” means firm and unwavering; “scathing” means severely critical.<br>“Steadiness” is a noun, while “steadfastly” and “steadily” are adverbs.<br>“Scathe” and “scathes” are verb forms, not adjectives.<br><br><b>Hence, the correct answer is option (3): steadfast, scathing.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":84,"local_id":"50084","quid":"Q1000073764","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Mohit said to Ananya, “Don't make a mountain out of a molehill.”<br>What does this idiom mean? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Don't exaggerate a small problem"},"2":{"en":"Work hard to achieve success"},"3":{"en":"Keep your emotions under control"},"4":{"en":"Be cautious while making decisions"}},"answer":"1","solution":{"en":"<b>Make a mountain out of a molehill (छोटी बात को बड़ा बनाना)</b><br>It means exaggerate a minor issue into something much more serious.<br>Example: “It was only a small error; don’t make a mountain out of a molehill.”<br>Hard work, emotional control and cautious decisions do not express exaggeration.<br><br><b>Hence, the correct answer is option (1): Don't exaggerate a small problem.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":85,"local_id":"50085","quid":"Q1000073765","section":"ENGLISH","topic":"Phrasal Verbs","question":{"en":"Improve the sentence using the correct phrasal verb of the underlined word.<br>She <u>ran out</u> her old friends at the mall yesterday. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"ran after"},"2":{"en":"ran into"},"3":{"en":"ran down"},"4":{"en":"ran over"}},"answer":"2","solution":{"en":"<b>Run into (संयोग से मिलना) = meet someone unexpectedly.</b><br>Correct sentence: “She <b>ran into</b> her old friends at the mall yesterday.”<br><b>Run after (पीछा करना)</b> = chase<br><b>Run down (टक्कर मारना/आलोचना करना)</b> = hit or criticize; <b>run over (कुचलना)</b> = hit with a vehicle<br><br><b>Hence, the correct answer is option (2): ran into.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":86,"local_id":"50086","quid":"Q1000073766","section":"ENGLISH","topic":"Phrasal Verbs","question":{"en":"Improve the sentence using the correct phrasal verb of the underlined wards.<br>The teacher asked him to <u>make down</u> a plan for the project. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"make up"},"2":{"en":"make over"},"3":{"en":"make out"},"4":{"en":"make off"}},"answer":"1","solution":{"en":"<b>Make up (बनाना, रचना करना) = devise or create a plan.</b><br>Correct sentence: “The teacher asked him to <b>make up</b> a plan for the project.”<br><b>Make over (रूपांतरित करना)</b> = transform<br><b>Make out (समझना)</b> = discern; <b>make off (भाग जाना)</b> = escape<br><br><b>Hence, the correct answer is option (1): make up.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":87,"local_id":"50087","quid":"Q1000073767","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the appropriate tense.<br>By the end of the fiscal year, the company ___ nearly 15% more than it had projected initially. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"has earned"},"2":{"en":"had earned"},"3":{"en":"will have earned"},"4":{"en":"was earning"}},"answer":"3","solution":{"en":"<b>Rule: Future perfect marks completion before a future deadline.</b><br>“By the end of the fiscal year” points to a future reference, so “will have earned” fits.<br>Present perfect and past perfect place the result in the present or past.<br>Past continuous describes an ongoing past action, not completion by a deadline.<br><br><b>Hence, the correct answer is option (3): will have earned.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":88,"local_id":"50088","quid":"Q1000073768","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Which of the following options is NOT one of the meanings of the homonymi “constitution”? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"The system of fundamental principles according to which a state or organisation is governed."},"2":{"en":"The physical or mental makeup of a person, especially in relation to health or temperament."},"3":{"en":"The formal disbandment of a legal contract between two or more parties."},"4":{"en":"The composition or structure of something, especially a material or compound."}},"answer":"3","solution":{"en":"<b>Constitution: governing principles, personal makeup, or composition.</b><br>A constitution can be a state’s fundamental law or a person’s physical and mental makeup.<br>It can also mean the composition or structure of a substance.<br>It does not mean the formal dissolution of a legal contract.<br><br><b>Hence, the correct answer is option (3): The formal disbandment of a legal contract between two or more parties.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":89,"local_id":"50089","quid":"Q1000073769","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Read the sentence below and choose the meaning of the idiom that best fits the context:<br>“Rahul will always be sorry that his father and he fought before he died and he never got a chance to bury the hatchet.”<br>What does the idiom “bury the hatchet” mean in this context? [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"To make peace and end a disagreement"},"2":{"en":"To hide something important from someone"},"3":{"en":"To feel guilty about a past mistake"},"4":{"en":"To physically bury a weapon in the ground"}},"answer":"1","solution":{"en":"<b>Bury the hatchet (विवाद समाप्त करना) = make peace and end a quarrel.</b><br>Rahul regrets that he and his father never reconciled.<br>Example: “The brothers finally buried the hatchet.”<br>Hiding something, feeling guilty and literal burial do not describe reconciliation.<br><br><b>Hence, the correct answer is option (1): To make peace and end a disagreement.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":90,"local_id":"50090","quid":"Q1000073770","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Choose the correct meaning of idiom:<br>To throw one's cap over the windmill [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"To act recklessly"},"2":{"en":"To challenge authority in public"},"3":{"en":"To mock traditional values"},"4":{"en":"To fall prey to delusion"}},"answer":"1","solution":{"en":"<b>Throw one’s cap over the windmill (अंधाधुंध जोखिम उठाना)</b><br>It means act recklessly or without regard for consequences.<br>Example: “He threw his cap over the windmill and invested all his savings.”<br>Public challenge, mocking tradition and delusion are not necessary parts of the idiom.<br><br><b>Hence, the correct answer is option (1): To act recklessly.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":91,"local_id":"50091","quid":"Q1000073771","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Choose the correct spelling for a word meaning “capable of burning”. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Corosive"},"2":{"en":"Corrosive"},"3":{"en":"Corrosiv"},"4":{"en":"Corroisive"}},"answer":"2","solution":{"en":"<b>Corrosive (क्षारक) = capable of chemically burning or eating away a substance.</b><br>The correct spelling has double “r” and ends in “-sive.”<br><b>Corosive</b> omits one “r”; <b>Corrosiv</b> omits the final “e.”<br><b>Corroisive</b> wrongly inserts “i” before “sive.”<br><br><b>Hence, the correct answer is option (2): Corrosive.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":92,"local_id":"50092","quid":"Q1000073772","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Identify the misspelt word. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Pulchritude"},"2":{"en":"Redolant"},"3":{"en":"Paroxysm"},"4":{"en":"Inchoate"}},"answer":"2","solution":{"en":"<b>Redolent (सुगंधित/स्मरण कराने वाला) = fragrant or strongly reminiscent.</b><br><b>Redolant</b> wrongly uses “a” instead of “e” in the ending.<br><b>Pulchritude (सौंदर्य)</b> = beauty; spelling correct.<br><b>Paroxysm (तीव्र आवेग)</b> = sudden outburst; <b>inchoate (अधूरा)</b> = not fully formed.<br><br><b>Hence, the correct answer is option (2): Redolant.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":93,"local_id":"50093","quid":"Q1000073773","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Spot the correct spelling of a thorny ornamental plant genus. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Bouganvillea"},"2":{"en":"Bougainvillea"},"3":{"en":"Bougainvillaea"},"4":{"en":"Bougainvilea"}},"answer":"2","solution":{"en":"<b>Bougainvillea (बोगनविलिया) = a thorny ornamental plant genus.</b><br>The correct sequence includes “gain” and double “l” before “ea.”<br><b>Bouganvillea</b> omits “i” after “ga”; <b>Bougainvillaea</b> adds an extra “a.”<br><b>Bougainvilea</b> omits one “l.”<br><br><b>Hence, the correct answer is option (2): Bougainvillea.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":94,"local_id":"50094","quid":"Q1000073774","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Identify the misspelt word. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"Elucubrate"},"2":{"en":"Anachronism"},"3":{"en":"sovriquett"},"4":{"en":"Peremptory"}},"answer":"3","solution":{"en":"<b>Sobriquet (उपनाम) = a nickname.</b><br><b>Sovriquett</b> is incorrect: use “sobriquet,” with “b” and “e” in place of “v” and double “t.”<br><b>Elucubrate (परिश्रम से लिखना)</b> = produce a work through laborious effort; spelling correct.<br><b>Anachronism (कालभ्रम)</b> = chronological error; <b>peremptory (अंतिम/दबंग)</b> = insisting on immediate compliance.<br><br><b>Hence, the correct answer is option (3): sovriquett.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":95,"local_id":"50095","quid":"Q1000073775","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Find the part of the sentence that contains an error:<br>The vice-chancellor insisted that the policy (1)/ is to be revised (2)/ by the end of the quarter (3)/ to address the audit remarks. (4) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"(1)"},"2":{"en":"(2)"},"3":{"en":"(3)"},"4":{"en":"(4)"}},"answer":"2","solution":{"en":"<b>Rule: After “insisted that,” use the mandative subjunctive “be + past participle.”</b><br>Part (2) should read “the policy <b>be revised</b>,” not “is to be revised.”<br>“Should be revised” would also be correct.<br>The other parts are grammatically sound.<br><br><b>Hence, the correct answer is option (2): (2).</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":96,"local_id":"50096","quid":"Q1000073776","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Find the part of the sentence that contains an error:<br>A very few researchers (1)/ have attempted to replicate the study (2)/ under identical field conditions (3)/ due to logistical limitations. (4) [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"(1)"},"2":{"en":"(2)"},"3":{"en":"(3)"},"4":{"en":"(4)"}},"answer":"1","solution":{"en":"<b>Rule: “Very few” means a small number; the article “a” changes the intended expression.</b><br>Part (1) should read “<b>Very few</b> researchers.”<br>“A few” means some, while “very few” emphasizes scarcity.<br>The remaining parts are correct.<br><br><b>Hence, the correct answer is option (1): (1).</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":97,"local_id":"50097","quid":"Q1000073777","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Select the sentence containing the homonym of the highlighted word:<br>The professor critiqued the flawed <b>lemma</b> in the manuscript. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"The botanist identified a damaged lemma in the grass sample."},"2":{"en":"The lemma connects two axioms in formal logic."},"3":{"en":"She corrected a misapplied lemma in the proof."},"4":{"en":"The mathematician introduced a bridging lemma."}},"answer":"1","solution":{"en":"<b>Lemma: a subsidiary mathematical proposition; also a botanical bract.</b><br>The original sentence uses the logical or mathematical meaning.<br>Option 1 uses “lemma” for part of a grass flower, a different meaning.<br>Options 2, 3 and 4 retain the mathematical or logical sense.<br><br><b>Hence, the correct answer is option (1): The botanist identified a damaged lemma in the grass sample.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":98,"local_id":"50098","quid":"Q1000073778","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a logical sentence<br>P. within colonial land tenure frameworks<br>Q. Agrarian dispossession<br>R. was systemically legitimised<br>S. through cadastral mapping [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"QRSP"},"2":{"en":"QPRS"},"3":{"en":"PQRS"},"4":{"en":"PRSQ"}},"answer":"1","solution":{"en":"<b>Order: QRSP</b><br>Q supplies the subject “Agrarian dispossession,” and R gives the passive predicate.<br>S explains the mechanism: cadastral mapping.<br>P places the process within colonial land-tenure frameworks.<br><br><b>Hence, the correct answer is option (1): QRSP.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":99,"local_id":"50099","quid":"Q1000073779","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences in correct order to make a logical sentence<br>P. reveals the paradox<br>Q. in contemporary economic reforms<br>R. The exclusion of marginal voices<br>S. of inclusive rhetoric [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"RPSQ"},"2":{"en":"PRSQ"},"3":{"en":"RSQP"},"4":{"en":"RQSP"}},"answer":"1","solution":{"en":"<b>Order: RPSQ</b><br>R supplies the subject “The exclusion of marginal voices.”<br>P gives the predicate “reveals the paradox.”<br>S identifies the paradox as one of inclusive rhetoric, and Q places it in contemporary economic reforms.<br><br><b>Hence, the correct answer is option (1): RPSQ.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":100,"local_id":"50100","quid":"Q1000073780","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"A sentence is provided in indirect speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding direct speech.<br>The leader said that not for a moment did he believe the accusations. [SSC CGL 10/10/26 Shift 2]"},"options":{"1":{"en":"“Not for a moment did I believe the accusations,” said the leader."},"2":{"en":"“I never believed the accusations,” said the leader."},"3":{"en":"“Not even once I believed the accusations,” said the leader."},"4":{"en":"“I did not believe the accusations for a moment,” said the leader."}},"answer":"1","solution":{"en":"<b>Rule: Restore “he” to “I” and retain the negative adverbial inversion.</b><br>“Not for a moment did he believe” becomes “Not for a moment did I believe.”<br>B and D remove the emphatic opening and inversion.<br>C uses incorrect word order after “Not even once.”<br><br><b>Hence, the correct answer is option (1): “Not for a moment did I believe the accusations,” said the leader.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]}}};